import Foundation

private typealias E = EvidenceSeed

/// Alternate tellings, batch F: the same cases, played out another way.
extension StoryVariants {
    static let variantsF: [CaseTemplate] = [realtorEscrowTakeV1, chopShopTrucksV1, cyclistDawnHitRunV1, flowersAtWorkV1, lakeCabinRansomV1, roadMergeShootingV1, churchStairShoveV1, ranchPipeAssaultV1, raceTrackBrawlV1, schoolBoardContractV1, lyingWitnessStandV1, hiddenGunFriendV1, restaurantOrderHackV1, churchFireFormerV1, tireSparePillsV1, pawnStrawBuyV1, forgedDeedLotV1, cafeBurnedForInsuranceV1, groupHomeWanderFreezeV1, roofingWidowScamV1, loanSharkThreatsV1, bailBondsJailerV1, barnFeudFireV1, chaserStagedInjuriesV1, hayrideTractorWreckV1]

    static let realtorEscrowTakeV1 = SmallCases.make(
        key: "story.realtorEscrowTake",
        category: .whiteCollar,
        headlines: ["Mortgage Broker Diverted Client Closing Funds to Pay Own Debts", "Wire Went to the Wrong Account"],
        law: "embezzlement100k",
        threshold: 8,
        spec: "Embezzled over $100,000 belonging to {V} by a person in a position of trust, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A mortgage broker, {D}, wired $132,000 in closing funds from {V} to a personal account on {DATE}. The closing collapsed. {DL} says the wire was a clerical error.",
        state: [E(.document, 3, "Wire Records", "$132,000 to {D}'s account."), E(.document, 3, "Closing Instructions", "Funds to the title company."), E(.statement, 2, "Attorney", "The closing failed.")],
        defense: [E(.statement, 1, "Clerical", "{DL} says the wire was a clerical error.")],
        role: "Closing attorney",
        exam: [.direct("What happened with {V}'s closing funds?", "\"A mortgage broker, {D}, wired $132,000 of {V}'s closing funds to a personal account. The closing collapsed because of it.\""), .direct("What did the closing instructions require for the funds?", "\"That the funds go to the title company. They did not. They went to {DL}'s own account, and I saw the wire.\""), .direct("What did the wire records show after the closing failed?", "\"$132,000 to {D.his} account. About half was wired back within a week, after the report was made.\""), .direct("Who was supposed to receive the funds?", "\"The title company. The closing instructions name it and give the account.\""), .direct("What happened to the money?", "\"The wire went to a personal account in {D.his} name instead of the title company. When closing day came, the funds were not there and the sale collapsed.\""), .direct("What did you do when you discovered it?", "\"I called the bank and the buyer the same day, then filed a report. The buyer lost the contract and a rate lock.\""), .cross("{D} says the wire was a clerical error, doesn't {D.he}?", "\"Yes. And half was returned, as I said. I will say that those two facts are in {D.his} favor.\""), .cross("When was the first half returned to the title company?", "\"After the report was made, about a week later. It did not come back before then, as far as I know.\""), .cross("What happened to the rest of the money that was not returned?", "\"I do not know for certain. It appears to have been used, and we have not recovered it.\""), .cross("Half of the money was wired back a week later, wasn't it?", "\"Yes, about half, after we demanded it. The other half stayed in {D.his} account for weeks.\""), .cross("A wire can be keyed wrong by accident, can't it?", "\"It can, but this one used an account number in {D.his} own name. That is not a random typo.\"")],
        defenseRole: "Bank officer",
        defenseExam: [.direct("Was half of the wired funds returned to the title company?", "\"Yes. About half was wired back to the title company within a week of the original transfer.\""), .direct("When exactly was that half returned to the title company?", "\"After the report was filed. It came back about a week after the original wire went out.\""), .direct("How was the returned money sent back to the title company?", "\"By wire from {D}'s account. The bank record shows the transfer, and I handled that wire myself.\""), .direct("What is your role at the bank?", "\"I am an officer who handles wire transfers. I reviewed this wire after the complaint came in.\""), .direct("What did the wire record show?", "\"A $132,000 outgoing wire from the trust account to an account in {D.his} name. It was initiated with {D.his} credentials.\""), .direct("Was there anything unusual about it?", "\"The destination was different from the closing instructions on file. A second check should have caught that.\""), .cross("Was the rest of the money ever returned to the title company?", "\"No. About half remained missing at the time I last checked, and I do not know if it has been repaid.\""), .cross("Did {D} explain the first wire as a mistake to the bank?", "\"Yes. {D.He} said it was a clerical error. We have not been able to confirm that explanation.\""), .cross("Did you hear that the defendant used the funds for a business loan?", "\"I heard that from others. I do not have the details, and I would not want to guess.\""), .cross("The wire was approved, wasn't it?", "\"Yes. Our system accepted it without a flag.\""), .cross("You do not know why the defendant chose that account, do you?", "\"No. I only know what the records show.\"")],
        theory: ("{D} diverted closing funds.", "A clerical error."),
        allocution: "\"It was a clerical error. I meant to wire the funds to the title company and I sent them to the wrong account. I wired half back within a week. I paid a business loan with part of it, which I know was wrong. I meant to fix it, and I'm sorry to {V}.\"",
        truths: ("{DL} paid a business loan with the funds.", "Half was wired back in a week."),
        defendant: [.direct("Was the wire to your account a mistake?", "\"Yes. It was a clerical error. I meant to wire the funds to the title company, and I sent it to my own account.\""), .direct("What did you do when you noticed the error?", "\"I wired half back within a week. I wanted to fix it as soon as I could, and that is what I did.\""), .direct("Where did the rest of the money go after that?", "\"I paid a business loan with it. I know that was wrong. I should have returned all of it.\""), .direct("What is your role?", "\"I am a mortgage broker who coordinates the paperwork and funds for closings. I send wires on instructions from the lender.\""), .direct("How did the wire go to your account?", "\"I was moving funds between accounts at a busy time and selected the wrong one. I did not notice until the title company called.\""), .direct("What did you do with the money?", "\"Part went to a payment on my business loan before I realized. I wired half back as soon as I could.\""), .cross("You paid a business loan with {V}'s closing funds, didn't you?", "\"Yes. I did. I should not have touched that money at all, and I regret it more than I can say.\""), .cross("You returned half only after a report was made, didn't you?", "\"Yes. I should have done it sooner. I waited until I was caught, and I realize how that looks.\""), .cross("A clerical error does not pay a business loan, does it?", "\"No. It does not. I used the money for the loan, and that was my decision and my mistake.\""), .cross("You kept half for a week after being told, didn't you?", "\"Yes. I did not have it all on hand.\""), .cross("Half of the money was wired back only after the closing failed, wasn't it?", "\"Yes. I wired half back a week later, once I understood the closing would not go forward. I should have done it the same day.\"")],
        openings: ("A mortgage broker, {D}, wired $132,000 of {V}'s closing funds to a personal account, and the closing collapsed. Half was wired back only after a report, and the rest paid a business loan.", "The defense will present evidence that the wire was a clerical error, that half was returned within a week, and that {D} meant to fix it."),
        closings: ("$132,000 in closing funds sent to {D}'s account, half returned only after a report, and the rest used to pay a business loan. That was a taking.", "A clerical error, half the money returned within a week. The State must prove {D} meant to take the funds from the start."),
        timeline: [(-7, "Funds arrive."), (0, "Closing day."), (0, "The wire is wrong."), (1, "{DL} is reported.")],
        identified: "Wire records.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "We lost the house. We had saved for years and sold our old place, and the closing day came with no money and no explanation. We moved in with relatives and our children changed schools. I want the funds returned and for this never to happen to another family.",
        doctrines: ["burdenOfProof"])

    static let chopShopTrucksV1 = SmallCases.make(
        key: "story.chopShopTrucks",
        category: .property,
        headlines: ["Deputies Find Motorcycle Chop Shop in a Rented Warehouse", "Frames Stripped and Re-Stamped"],
        law: "possStolen",
        threshold: 8,
        spec: "Possessed stolen vehicles and parts valued over $100,000, knowing them to be stolen, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Deputies raided a rented warehouse on {DATE} and found nine stripped motorcycles with re-stamped frames. {D} leased the warehouse. {DL} says a tenant used it.",
        state: [E(.physical, 3, "Frames", "Re-stamped frame numbers.", .search), E(.document, 3, "Lease", "Leased by {D}."), E(.digital, 2, "Phone Messages", "'Need two Harley frames.'")],
        defense: [E(.document, 1, "Tenant Lease", "An unsigned sublease.")],
        role: "Auto theft investigator",
        exam: [.direct("What did deputies find in the warehouse on {DATE}?", "\"Nine stripped motorcycles with re-stamped frame numbers. The frames were seized in the search.\""), .direct("Who leased the warehouse?", "\"{D}. The lease lists {DL} as the leaseholder, and {D.he} had keys to the space.\""), .direct("What messages tie to the operation?", "\"A phone message that read, 'Need two Harley frames.' It looks like an order for stolen parts.\""), .direct("How did the raid come about?", "\"A neighbor reported noise and a steady flow of motorcycles at a rented warehouse. We watched for two days and then obtained a warrant.\""), .direct("How many people were in the warehouse?", "\"Three were present when the deputies arrived. One ran out the back and was stopped in the alley.\""), .direct("What did the phone messages say?", "\"Texts asking for two Harley frames and listing prices. They came from a number tied to the warehouse lease.\""), .cross("{DL} says a tenant used the warehouse, doesn't {D.he}?", "\"There's an unsigned sublease. I couldn't identify the subtenant.\""), .cross("Did you see {DL} re-stamp a frame?", "\"No. I wasn't there when the work was done. I found the frames and the messages.\""), .cross("Was the message sent to {DL}?", "\"It was on a phone tied to {D.him}. I can't say who read it.\""), .cross("An unsigned sublease exists, doesn't it?", "\"Yes, a paper naming a subtenant with no signature. We could not confirm who that person was.\""), .cross("The subtenant paid cash, didn't {D} say?", "\"Yes. {D.He} said rent was paid in cash each month.\"")],
        defenseRole: "Landlord's agent",
        defenseExam: [.direct("What is your role with the warehouse?", "\"I am an agent for the building owner, handling leases and collecting rent on several warehouses. I handled the paperwork on this one.\""), .direct("Who leased the warehouse?", "\"{D}. The lease lists {DF} as the only tenant, with no other names, and {DF} signed it in our office.\""), .direct("Did you know of any subtenant?", "\"I heard a passing remark once that someone else used part of the space. I never saw a document or a name.\""), .direct("How was the rent paid?", "\"In cash, every month, in an envelope that {D.he} brought to my office. That is not unusual for these buildings.\""), .direct("What did you notice at the warehouse?", "\"Motorcycles coming and going, which I assumed was a repair business. I did not go inside, and I never saw the back room.\""), .direct("What happened after the raid?", "\"I gave deputies the lease and the rent records. I told them everything I knew about how the rent was paid.\""), .cross("You do not know who the subtenant was, do you?", "\"No. I never saw a name or a face, and no sublease was ever given to my office.\""), .cross("You do not know what was done inside, do you?", "\"Only what the deputies told me afterward. I never walked through the building during the lease.\""), .cross("The lease names {D} alone, doesn't it?", "\"Yes, {D.he} alone. There is no second name on the lease or in my file.\""), .cross("You never saw a signed sublease, did you?", "\"No. The only paper I ever saw was the lease itself, and it was signed by {DF}.\""), .cross("You accepted cash without any questions, didn't you?", "\"Yes. I did, because tenants in these buildings often pay that way, and I never thought to ask more.\"")],
        theory: ("{D} ran a chop shop.", "A subtenant."),
        allocution: "\"I leased that warehouse for storing equipment and a small repair business, and I rented part to someone who answered an ad and paid cash. I never knew what was going on. Some of the bikes were left over from my earlier business.\"",
        truths: ("{DL} owned the stamping tools.", "The subtenant paid cash."),
        defendant: [.direct("What was the warehouse for?", "\"I leased it for storing equipment and for a small repair business on the side. I sublet part of it to a tenant for cash.\""), .direct("Who was the subtenant?", "\"Someone who answered an ad, paid cash, and said the space was for motorcycle storage. I never saw a signed paper.\""), .direct("Whose tools were the stamping tools?", "\"Some were mine, left from an earlier business. The subtenant used them with my permission.\""), .direct("What did you think was happening?", "\"I thought the tenant was repairing and storing bikes. I did not think it was a chop shop.\""), .direct("How did you react to the raid?", "\"I was shocked. I told deputies everything I knew about the tenant.\""), .direct("What did you do after you learned the subtenant had stripped bikes in your warehouse?", "\"I called the subtenant and got no answer. I should have gone to the sheriff, but I was afraid of being blamed for what happened there.\""), .cross("The lease is in your name, isn't it?", "\"Yes. The warehouse was mine, and anything inside is on my lease.\""), .cross("The stamping tools were yours, weren't they?", "\"Yes. I should not have let anyone use them.\""), .cross("Messages about frames came from a number tied to the warehouse, didn't they?", "\"So I was told. I did not send them.\""), .cross("You never got a signed sublease, did you?", "\"No. I took cash and a handshake.\""), .cross("Nine stripped motorcycles is a big operation, isn't it?", "\"Yes, and I should have noticed more.\"")],
        openings: ("Deputies raided a rented warehouse and found nine stripped motorcycles with re-stamped frames. {D} leased the warehouse, and a message said, 'Need two Harley frames.' The State will show the frames and the lease.", "The defense will present an unsigned sublease to a tenant, a landlord's agent who saw a stranger, and a leaseholder who rarely went inside. Listen closely to the witnesses."),
        closings: ("Nine stripped motorcycles, re-stamped frames, stamping tools owned by {D}, and messages asking for Harley frames. The lease is in {D.his} name, and the work was done under {D.his} roof.", "An unsigned sublease and a tenant who paid cash. The State has not proved {D} ran the shop rather than rented space to someone who did."),
        timeline: [(-30, "The sublease, {DL} says."), (0, "Morning: the raid."), (0, "Noon: frames logged."), (1, "{DL} is charged.")],
        identified: "A raid.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure"])

    static let cyclistDawnHitRunV1 = SmallCases.make(
        key: "story.cyclistDawnHitRun",
        category: .traffic,
        headlines: ["Jogger Killed in Dark Morning Run; Truck Left the Scene", "Side Mirror Housing on the Shoulder"],
        law: "hitAndRun",
        threshold: 8,
        spec: "Left the scene of a crash causing death without stopping, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a jogger, was killed on a county road before sunrise on {DATE} by a vehicle that did not stop. A mirror housing matched {D}'s truck. {DL} says the truck was parked at a job site.",
        state: [E(.physical, 3, "Mirror Housing", "Matches {D}'s truck.", .search), E(.forensic, 3, "Autopsy", "Fatal blunt trauma."), E(.digital, 2, "Phone Location", "{DL}'s phone on the road.")],
        defense: [E(.statement, 1, "Job Site", "{DL} says the truck was at a job site.")],
        role: "Highway Patrol trooper",
        exam: [.direct("What happened on the county road before sunrise on {DATE}?", "\"{V}, a jogger, was killed by a vehicle that did not stop. The autopsy found fatal blunt trauma.\""), .direct("What was recovered?", "\"A mirror housing at the scene that matches {D}'s truck.\""), .direct("What else ties {DL} to the road?", "\"{D.his} phone was on the road at that time.\""), .direct("What time did the driver call it in?", "\"A few minutes before six. Dispatch's log shows the exact time of the call.\""), .direct("What evidence pointed to the vehicle?", "\"A broken mirror housing lay near {V}. The housing was from a model of truck like {DL}'s and the pieces fit.\""), .direct("What about {D}'s phone?", "\"Location records put {D.his} phone on that stretch of road around 5:40. {D.He} says the phone was in the truck.\""), .cross("{DL} says the truck was parked at a job site, doesn't {D.he}?", "\"A foreman puts the truck at the site that morning. I can't say the exact time.\""), .cross("Is a mirror housing unique?", "\"It's a model part. It matches the truck, but many trucks share the model.\""), .cross("Did you see {DL}'s truck at the scene?", "\"No. I found the housing. No witness identified the truck.\""), .cross("The truck was seen at a job site that morning, wasn't it?", "\"A foreman says the truck was at the job site at six. That is after the crash window, but the site is on the same road.\""), .cross("{D} repaired the mirror that week, didn't {D.he}?", "\"Yes. The repair was after the crash, and it adds to the question.\"")],
        defenseRole: "Site foreman",
        defenseExam: [.direct("What is your role at the job site?", "\"I am the site foreman at the project where {D} was working that morning. I start at six every day and open the gate myself.\""), .direct("What did you see of the truck?", "\"It was parked inside the site when I arrived at six, with tools already on the tailgate. {D.He} was unloading it and getting ready.\""), .direct("How did the defendant seem that morning?", "\"Calm and normal, with a coffee in hand. {D.He} said good morning and started setting up the saws without any sign of trouble.\""), .direct("What did you notice about the truck?", "\"Nothing unusual. I did not look closely at the mirror or the front end, and nobody mentioned a problem that day.\""), .direct("How far is the site from where the jogger was found?", "\"A few miles down the same county road. A truck could drive between them in under ten minutes.\""), .direct("What did you do when deputies came?", "\"I told them what time I saw the truck and gave them the site log. I also gave them my phone number.\""), .cross("You did not see the truck before six, did you?", "\"No. I was not at the site earlier, so I cannot say where the truck was at 5:40.\""), .cross("You do not know where the defendant drove from, do you?", "\"No. I only know the truck was parked and {D.he} was unloading when I arrived.\""), .cross("The mirror was repaired that week, wasn't it?", "\"I heard that later. I did not notice a broken mirror on the truck that morning.\""), .cross("The site is on the same road as the crash, isn't it?", "\"Yes, a few miles from where the jogger was found.\""), .cross("Ten minutes would be enough to get from the road to the site, wouldn't it?", "\"Yes, easily. I cannot rule that out.\"")],
        theory: ("{D} killed a jogger and left.", "The truck was elsewhere."),
        allocution: "\"I was at my job site that morning, and the truck was there. I may have driven that road earlier or later, as I often do, but I wasn't on it that morning. I would never leave someone on the road. I'm so sorry for {V}'s family and their loss.\"",
        truths: ("{DL} repaired the mirror that week.", "A foreman saw the truck at the site at 6."),
        defendant: [.direct("Where was your truck that morning?", "\"At my job site. I start early, and the truck was there. I didn't drive on that road.\""), .direct("Why was your phone on the road?", "\"I may have driven it earlier or later. I use that road often. I wasn't there at the time.\""), .direct("Did you hit {V}?", "\"No. I would never leave someone on the road. It wasn't me.\""), .direct("Where were you that morning?", "\"I was driving to a job site on that road a little after five-thirty. I did not see anyone.\""), .direct("What happened to the mirror?", "\"I clipped it on a fence post a couple of days earlier. I fixed it the next day.\""), .direct("What do you say about the phone?", "\"It was in the truck with me. That road is how I get to work.\""), .cross("The mirror housing matches your truck, doesn't it?", "\"That's what they say. It's a common model. I can't explain it.\""), .cross("Your phone was on that road, wasn't it?", "\"Yes. It's my commute. That doesn't mean I was there at that moment.\""), .cross("Your truck has damage to its mirror, doesn't it?", "\"It had been bumped before. I'd noticed it earlier.\""), .cross("You were on that road at 5:40, weren't you?", "\"Yes. I drove it every day, and I did not hit anyone.\""), .cross("The mirror housing matched your truck, didn't it?", "\"So I was told. I do not know how a piece from my truck got there.\"")],
        openings: ("{V}, a jogger, was killed before sunrise by a vehicle that did not stop. A mirror housing at the scene matches {D}'s truck, and {DL}'s phone was on the road. The State will show the housing, the autopsy, and the phone.", "Jurors will also see a truck at a job site that morning, a foreman who saw it, and a mirror housing shared by many trucks of that model."),
        closings: ("A jogger killed, a mirror housing that matches {D}'s truck, and {D.his} phone on the same road. The pieces point to {D.him}.", "The truck was at a job site, and a mirror part is not unique. The State has not proved {D} was driving."),
        timeline: [(0, "5:40 a.m.: the crash."), (0, "5:50 a.m.: a driver finds {V}."), (2, "The match."), (4, "{DL} is charged.")],
        identified: "A mirror housing.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "{V} ran every morning, rain or shine, on that same county road before sunrise. {V} never came home from the last run. Our family goes to that spot each year, and each year there is another empty chair. Whoever left {V} there should have stopped.",
        doctrines: ["alibi"],
        genders: ["V": .female])

    static let flowersAtWorkV1 = SmallCases.make(
        key: "story.flowersAtWork",
        category: .family,
        headlines: ["Man Left Teddy Bear on Ex's Car Hood in Violation of Protective Order", "Parking Garage Camera Shows Him"],
        law: "dvpoViolation",
        threshold: 7,
        spec: "Willfully violated a valid domestic violence protective order, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} left a teddy bear on {V}'s car hood in a parking garage on {DATE} despite a protective order. {DL} says it was left by a coworker.",
        state: [E(.video, 3, "Garage Camera", "{D} places a bear."), E(.document, 3, "Order", "No contact within 100 feet."), E(.statement, 2, "Security", "{D} was in the garage.")],
        defense: [E(.statement, 1, "Coworker", "{DL} says a coworker left it.")],
        role: "Garage security guard",
        exam: [.direct("What did you see in the garage on {DATE}?", "\"{D} placed a teddy bear on {V}'s car hood. The garage camera shows it.\""), .direct("What order was in place?", "\"A protective order with no contact within 100 feet. {D.He} was in the garage.\""), .direct("What did you do?", "\"I reported it. I knew about the order. I was concerned for {V}.\""), .direct("How long did {DL} stay at the car?", "\"Only a moment. {DL} set the bear down, looked at it, and then walked back the way {D.he} had come.\""), .direct("What is the protective order?", "\"It prohibits {DL} from contacting {V} or coming within 100 feet. It was served weeks earlier.\""), .direct("Was {D} in the garage that morning?", "\"Yes. A security log shows {D.his} badge at the garage at 8 a.m.\""), .cross("{DL} says a coworker left it, doesn't {D.he}?", "\"The camera shows {DL} placing the bear. I can't speak to who else was involved.\""), .cross("Did {DL} speak to {V}?", "\"No. {DL} put the bear down and left. There was no contact.\""), .cross("Was {DL} aggressive?", "\"No. {D.He} was calm. It was a gentle gesture, but it was prohibited.\""), .cross("The bear was left by someone else, according to the defendant, wasn't it?", "\"That is what {D.he} says. {D.He} says a coworker asked to carry it.\""), .cross("You do not know whose idea the bear was, do you?", "\"No. I know only what the camera shows.\"")],
        defenseRole: "Coworker",
        defenseExam: [.direct("Do you work with {DL} and {V}?", "\"Yes. We work in the same office.\""), .direct("Did a gift come up?", "\"I mentioned a gift for {V} that week. I can't say who delivered it.\""), .direct("Did {DL} say anything?", "\"{D} knew about the order. {D.He} was careful, I thought.\""), .direct("How do you know {D}?", "\"We work in the same department and sit near each other. I asked {D.him} for a favor that morning before work.\""), .direct("What did you ask the defendant to do?", "\"To carry a teddy bear to the garage for me, because my hands were full of boxes. I told {D.him} which level to leave it on.\""), .direct("Whose car was it?", "\"I did not tell {DF}. I told {DF} it was a surprise for someone and to set it on a hood.\""), .cross("Did you leave the bear?", "\"I'd rather not say. I'm only here about what I know.\""), .cross("Did you ask {DL} to deliver it?", "\"I can't say that. I only talked about a gift.\""), .cross("Did you see {DL} in the garage?", "\"No. I wasn't there. I didn't see {DL} in the garage.\""), .cross("You knew about the protective order, didn't you?", "\"I had heard a rumor about some kind of order. I did not connect it to the person whose car it was.\""), .cross("You knew where the bear was meant to go, didn't you?", "\"I knew it was meant as a gift, and I'd rather not say more than that.\"")],
        theory: ("{D} violated an order.", "A coworker."),
        allocution: "\"A coworker asked me to carry a bear for a group gift, and I didn't think about where I was walking. I know about the order, and I forgot it applied to that spot. I put the bear down and left, and I never tried to see or speak to {V}. I should have stayed away.\"",
        truths: ("{DL} had texted {V} that morning.", "A coworker had asked {DL} to carry it."),
        defendant: [.direct("Why did you put the bear on {V}'s car?", "\"A coworker asked me to carry it for a group gift. I didn't think about the order that day.\""), .direct("Did you know about the protective order?", "\"Yes. But I was helping a coworker, and I forgot it applied to that spot.\""), .direct("Did you mean to contact {V}?", "\"No. I put the bear down and left. I didn't try to see or speak to {V}.\""), .direct("How did you end up with the bear?", "\"A coworker asked me to carry it to the garage because their hands were full. I did not look at whose car it was.\""), .direct("What did you do with it?", "\"I set it on a car hood where the coworker told me. I left right after.\""), .direct("Did you know it was {V}'s car?", "\"Not at first. I realized when I saw the plate on my way out.\""), .cross("The order barred you within 100 feet, didn't it?", "\"Yes. I knew. I made a mistake.\""), .cross("You were in the garage where {V} parks, weren't you?", "\"Yes. I went to leave the bear. It was careless.\""), .cross("The camera shows only you, doesn't it?", "\"Yes. I carried it. The idea was a coworker's.\""), .cross("You texted {V} that morning, didn't you?", "\"Yes, a short message. I know I should not have.\""), .cross("You were served with the protective order weeks before, weren't you?", "\"Yes, I was served weeks earlier and I read it. I have no good excuse for forgetting it that morning.\"")],
        openings: ("Despite a protective order barring contact within 100 feet, {D} placed a teddy bear on {V}'s car hood in a parking garage, as the garage camera shows. The State will show the camera and the order.", "The defense evidence includes a gift idea among coworkers, a person who carried the bear without thinking of the order, and no contact with {V}."),
        closings: ("A teddy bear on {V}'s hood, a protective order barring contact, and {D} on the garage camera and badge log. The order says stay away, and the camera shows {DL} approaching.", "A coworker asked {D} to carry a bear, and {D.he} did not know whose car it was. The State has not proved {DL} knowingly violated the order, and a favor for a coworker is not harassment."),
