        law: "kidnapping1",
        threshold: 8,
        spec: "Unlawfully confined and restrained {V}, a minor, for ransom, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, fifteen, was held in a hunting camp shed for two days on {DATE} while a $30,000 demand was texted to {V.his} parents. {D}, a family friend, was arrested. {DL} says {V} chose to stay.",
        state: [E(.digital, 3, "Ransom Text", "A demand from a prepaid phone."), E(.physical, 3, "Shed", "A padlock outside the shed.", .search), E(.statement, 3, "Teen", "'I couldn't leave.'")],
        defense: [E(.statement, 1, "Chose", "{DL} says {V} chose to stay.")],
        role: "Detective",
        exam: [.direct("What happened to {V}?", "\"{V}, fifteen, was held in a hunting camp shed for two days while a $30,000 demand was texted to {V}'s parents.\""), .direct("What was found at the shed?", "\"A padlock on the outside. The ransom text came from a prepaid phone.\""), .direct("What did {V} tell you?", "\"'I couldn't leave.' {V} said the door was locked from the outside.\""), .direct("Who found {V}?", "\"A hunter walking past the camp. He heard knocking from inside the shed.\""), .direct("What did you find at the camp?", "\"{V} in a shed with a latched door, unharmed but frightened. {V} said, I could not leave.\""), .direct("How was {D} identified?", "\"The prepaid phone was traced to a store where {D.he} paid cash. {D.He} owed about $25,000 at the time.\""), .cross("{D} says {V} chose to stay, doesn't {D.he}?", "\"Yes. The teen sent a cheerful text at one point, I understand.\""), .cross("Did {D} owe money?", "\"Yes. {D.He} owed $25,000. That is part of why we looked at {D.him}.\""), .cross("Was {V} hurt?", "\"No. {V} was frightened but unharmed.\""), .cross("{V} sent a cheerful text during the weekend, didn't {V.he}?", "\"Yes, a short message saying all was fine. We do not know under what pressure it was sent.\""), .cross("The shed door latched from the outside, didn't it?", "\"Yes. It had a bar latch on the outside.\"")],
        defenseRole: "Camp neighbor",
        defenseExam: [.direct("Did you see {V} at the hunting camp during those two days?", "\"Outside once. {V} was walking around near the shed, and I noticed because I do not usually see anyone there.\""), .direct("Did {V} seem afraid or upset when you saw {V.him}?", "\"No. {V} looked relaxed and normal. I did not see anything that made me think anything was wrong.\""), .direct("Was {V} free to leave the camp, as far as you could see?", "\"Unknown. I did not see a lock or anyone stopping {V} from leaving, but I was not watching closely.\""), .direct("How do you know {D}?", "\"I am a neighbor at the next campsite. I saw {D} and a teen arrive on Friday.\""), .direct("What did you see that weekend?", "\"The teen walked around the camp and joked with us. {D.He} seemed relaxed.\""), .direct("Did the teen look afraid?", "\"Not on Friday. On Saturday the teen stayed near the shed.\""), .cross("How far were you from the shed when you saw {V}?", "\"A couple hundred yards. I saw {V} only briefly, and I could not make out any detail of the shed door.\""), .cross("Did you speak to {V} at any point during those two days?", "\"No. I did not talk to {V}. I only saw {V} from a distance and did not get any closer.\""), .cross("Did you see a padlock on the outside of the shed?", "\"I did not look. I do not know whether a padlock was there, since I was too far away to see.\""), .cross("You did not hear the ransom text, did you?", "\"No. I only know what I saw.\""), .cross("Did you walk around the back of the shed?", "\"No. I stayed on the front side, so I can't say what was behind it.\"")],
        theory: ("{D} held a teen.", "A visit."),
        allocution: "\"{V} chose to stay at that camp, and I never locked anyone in that shed. I did not send that text, and I don't know who did. The door was locked on the outside to protect the equipment inside. I'm not proud of any of it, and I'm sorry to {V}'s parents.\"",
        truths: ("{DL} owed $25,000.", "The teen sent a cheerful text."),
        defendant: [.direct("Did you hold {V} in the shed?", "\"No. {V} chose to stay at the camp. I did not lock anyone in.\""), .direct("Did you send a ransom demand?", "\"No. I did not send that text. I do not know who did.\""), .direct("What about the padlock?", "\"It was for the equipment inside. It was on the outside, but it was not locked on {V}.\""), .direct("What was your plan for the trip?", "\"A weekend of hunting with a family friend's child. I wanted to give the teen a break.\""), .direct("How cold was it that weekend?", "\"Below freezing at night. There was a wood stove in the main cabin, and the shed had none.\""), .direct("What about the ransom text?", "\"I never sent it. I do not know who did.\""), .cross("{V} says {V.he} could not leave. Is {V} lying?", "\"I think {V} is mistaken. {V} sent a cheerful text.\""), .cross("The ransom text came from a prepaid phone. Is it yours?", "\"No. I did not buy it.\""), .cross("You owed $25,000, didn't you?", "\"Yes, and I was under pressure. That does not mean I took anyone.\""), .cross("The shed latches from the outside, doesn't it?", "\"Yes, and someone latched it. I do not know who.\""), .cross("You were the only adult at the camp with {V}, weren't you?", "\"There were other campers around, but I was the adult who brought {V} there and I was responsible for {V.him}.\"")],
        openings: ("{V}, fifteen, was held in a hunting camp shed for two days while a $30,000 demand was texted to {V}'s parents. {D}, a family friend, owed $25,000, and a padlock was on the outside of the shed.", "Weigh the defense proof, which will show that {V} chose to stay, sent a cheerful text, and that {D} never held anyone against their will."),
        closings: ("A padlock on the outside of the shed, a $30,000 demand from a prepaid phone, and a teen who says {V.he} could not leave. {D} owed $25,000 at the time.", "A teen who sent a cheerful text and was seen walking outside. The State must prove {D} held {V} against {V.his} will, and the evidence leaves real doubt."),
        timeline: [(0, "Friday: the trip."), (0, "Saturday: the demand."), (0, "Sunday: deputies."), (0, "Sunday: arrest.")],
        identified: "A phone.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "I still can't sleep. I was fifteen, and I spent two days in that shed not knowing if anyone was coming. I jumped at every sound outside. My parents were getting texts about money while I sat in the dark. I don't go to the lake anymore.",
        doctrines: ["necessity"])

    static let roadMergeShootingV1 = SmallCases.make(
        key: "story.roadMergeShooting",
        category: .violent,
        headlines: ["Driver Fatally Shot in Mall Parking Lane After Dispute Over a Space, Tire Iron Beside the Body", "Surveillance and Dash Camera Disagree on Who Struck First"],
        law: "murder2",
        threshold: 9,
        spec: "Unlawfully killed {V} with malice, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} and {D} argued over a parking space outside a mall on {DATE}. {V} got out of a car holding a tire iron and walked toward {DL}'s truck. {DL}, still in the truck, fired one shot through the open window. {V} died on the pavement. A dash camera and the mall's cameras recorded the exchange. A pistol was in {D.his} hand when deputies arrived. {DL} says {V} raised the tire iron and {D.he} feared for {D.his} life.",
        state: [E(.video, 3, "Mall Camera", "{V} walks toward the truck holding a tire iron."), E(.forensic, 3, "Ballistics", "One round from {D}'s pistol."), E(.statement, 3, "Bystander", "Heard {D} yell 'back up' before the shot.")],
        defense: [E(.physical, 1, "Tire Iron", "A tire iron on the pavement near {V}."), E(.statement, 1, "Fear", "{DL} says {V} raised the iron.")],
        role: "Mall security officer",
        exam: [.direct("What does the mall camera show?", "\"{V} getting out of a car holding a tire iron and walking toward {D}'s truck after an argument over a parking space.\""), .direct("What happened when {V} reached the truck?", "\"{DL}, still seated in the truck, fired one shot through the open window. {V} fell and died on the pavement.\""), .direct("What did a bystander tell you?", "\"That {D.he} yelled 'back up' before the shot. A pistol was in {D.his} hand when deputies arrived.\""), .direct("What did you see on the mall cameras?", "\"At about 1:08, {V} gets out of a car holding a tire iron and walks toward {DL}'s truck. A minute later, there is a shot, and {V} falls.\""), .direct("What did a bystander say?", "\"The bystander heard {DL} yell back up before the shot. I took a statement that matched the video.\""), .direct("What did deputies find?", "\"A pistol in {D.his} hand, a tire iron on the pavement near {V}, and one spent casing in the truck. We recovered the round from {V}.\""), .cross("{D} says {V} raised the tire iron and {D.he} feared for {D.his} life, doesn't {D.he}?", "\"The camera shows {V} holding the tire iron as {V} approached. I will say that I could not see it raised.\""), .cross("How far was {V} from the truck when the shot was fired?", "\"About ten feet. That is what the ballistics and the camera together suggest.\""), .cross("Did the defendant warn {V} before firing?", "\"A bystander heard {DL} yell 'back up.' I did not hear it myself.\""), .cross("{V} was ten feet from the truck when the defendant fired, wasn't {V.he}?", "\"Close to it, yes. {DL} fired from inside the truck with the window open.\""), .cross("The tire iron was in {V}'s hand when {V} got out, wasn't it?", "\"It was, on the mall camera. I cannot say whether it was raised at the instant of the shot.\"")],
        theory: ("{D} shot a driver over a parking space.", "A driver who feared a tire iron."),
        allocution: "\"{V} came at me with a tire iron after we argued over a parking space, and I yelled to back up twice. {V} kept coming, and I raised my gun. I keep it in the console for my safety. I lost my temper, and I'm sorry for what I did, and for {V}'s family.\"",
        truths: ("{DL} had a window rolled down and a pistol in the console.", "{DL} fired as {V} was ten feet away."),
        defendant: [.direct("Did you shoot {V}?", "\"Yes. {V} came at me with a tire iron after we argued over a parking space, and I fired once because I was afraid.\""), .direct("Why did you have a pistol in your truck?", "\"I keep it in the console for my safety. I did not bring it out for the argument. I grabbed it when {V} came toward me.\""), .direct("Did you warn {V} before you fired?", "\"I yelled 'back up.' I yelled it twice. {V} kept coming, and I raised the pistol.\""), .direct("What was the argument about?", "\"A parking space at the mall. {V} and I shouted at each other for a few minutes before {V} walked away.\""), .direct("What did {V} do next?", "\"Got out of a car with a tire iron and walked toward my truck, yelling. I rolled the window down and told {V} to back up.\""), .direct("Why did you fire?", "\"I saw {V} raise the tire iron and thought I was about to be hit. I was afraid for my life.\""), .cross("{V} was ten feet away when you fired, wasn't {V.he}?", "\"Yes. About that. It felt much closer to me, and I saw the tire iron coming up.\""), .cross("You were inside a truck with the window rolled down. Couldn't you have driven away?", "\"I was boxed in. I did not think I could pull out in time. I now wish I had tried.\""), .cross("{V} died on the pavement. Do you accept that you caused that?", "\"Yes. I did. I did not want anyone to die.\""), .cross("You had a pistol in the console, didn't you?", "\"Yes, loaded. I keep it for protection.\""), .cross("You rolled the window down yourself while {V} was walking toward you, didn't you?", "\"Yes, I rolled it down to tell {V.him} to back off. I did not think it through any further than that.\"")],
        openings: ("{V} and {D} argued over a parking space outside a mall. {V} got out holding a tire iron and walked toward {DL}'s truck, and {DL}, still seated, fired one shot through the open window. {V} died on the pavement.", "Jurors will hear that {V} raised the tire iron as {V} approached, that {D} yelled a warning first, and that {DL} fired in fear for {D.his} life."),
        closings: ("A parking argument, a tire iron, one shot through an open window, and {V} dead on the pavement. {D} was seated in a truck, with a way to drive off.", "A person walking up with a tire iron after a shouted warning, and one shot fired in fear from inside a truck. The State must prove {D} was not in reasonable fear of serious harm."),
        timeline: [(0, "1:05 p.m.: the argument starts."), (0, "1:08 p.m.: {V} gets out with the iron."), (0, "1:09 p.m.: the shot."), (0, "1:12 p.m.: security calls 911."), (0, "1:20 p.m.: deputies arrive.")],
        identified: "A mall camera.",
        mood: .wantsConviction,
        doctrines: ["selfDefense", "imperfectSelfDefense", "lesserIncluded"],
        genders: ["V": .male])

    static let churchStairShoveV1 = SmallCases.make(
        key: "story.churchStairShove",
        category: .violent,
        headlines: ["Elderly Pantry Visitor Falls From Loading Dock After Shove", "Line Dispute Turned Physical"],
        law: "volManslaughter",
        threshold: 7,
        spec: "Unlawfully killed {V} without malice, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, seventy-three, died on {DATE} after falling from a loading dock at a food pantry when {D} shoved {V.him} over a place in line. {DL} says {V} stumbled.",
        state: [E(.statement, 3, "Volunteer", "'I saw a shove.'"), E(.forensic, 3, "Autopsy", "Fatal fall injuries."), E(.video, 2, "Dock Camera", "Two men at the edge.")],
        defense: [E(.statement, 1, "Stumble", "{DL} says {V} stumbled.")],
        role: "Pantry volunteer",
        exam: [.direct("What did you see at the food pantry dock on {DATE}?", "\"{V}, who was seventy-three, was standing near the edge of the loading dock when {D} shoved {V} over a place in line. {V} fell.\""), .direct("What did the dock camera show?", "\"Two people at the edge. It shows the shove and the fall.\""), .direct("What happened to {V}?", "\"{V} died from the fall. The autopsy found fatal fall injuries.\""), .direct("Who else was on the dock?", "\"Two volunteers and a driver unloading a truck. All of us saw the argument start.\""), .direct("Who was shoved?", "\"{V}, who was seventy-three. {V} fell backward to the lot below and did not get up.\""), .direct("What happened afterward?", "\"We called 911 and paramedics arrived. {V} was taken to the hospital and died about an hour later.\""), .cross("{DL} says {V} stumbled, doesn't {D.he}?", "\"I saw a shove. But it happened quickly.\""), .cross("Was the line crowded?", "\"Yes. People were close together. It was a busy day.\""), .cross("Did you see {DL}'s hands on {V}?", "\"I saw {DL} push. I saw {V} go over the edge.\""), .cross("The dock edge had no rail, did it?", "\"No. It is a loading edge with a drop of about four feet.\""), .cross("You did not see the first words, did you?", "\"No. I saw the push.\"")],
        defenseRole: "Pantry director",
        defenseExam: [.direct("Do you direct the pantry?", "\"Yes. I run the pantry and the dock line.\""), .direct("How is the line managed?", "\"We try to keep it orderly. Sometimes it's tight and people get frustrated.\""), .direct("Is the dock safe?", "\"It has hazards. It's a loading dock. We warn people to stay back.\""), .direct("What is your role at the pantry?", "\"I am the director. I run the volunteers, schedule the lines, and oversee the loading dock every Saturday morning.\""), .direct("What did you see that morning?", "\"I heard shouting and saw {D} and {V} near the edge of the dock. From where I stood, I could not tell who moved first.\""), .direct("What was {V}'s condition?", "\"Older and unsteady. {V} came every week and walked with a cane, and often held the rail where there was one.\""), .cross("Did you see the push?", "\"No. I wasn't on the dock. I only know the setup.\""), .cross("Has anyone fallen before?", "\"I don't recall a fall. We've had close calls.\""), .cross("Are people allowed to push?", "\"No. Never. It's against our rules.\""), .cross("You did not see a shove, did you?", "\"I was about ten feet away and saw a struggle at the edge. I cannot say who pushed whom.\""), .cross("The dock had no rail at that edge, did it?", "\"No. We had asked the building owner for one twice, and it was never installed.\"")],
        theory: ("{D} shoved a man to his death.", "A stumble."),
        allocution: "\"We were in a crowded line, and I was frustrated about waiting. I put my hand out when {V} stepped in front of me, and {V} stumbled. I don't remember a hard shove. A person died, and it was horrible. I wish I could change it, and I'm sorry to {V}'s family.\"",
        truths: ("{DL} was angry about waiting.", "The dock edge had no rail."),
        defendant: [.direct("What happened on the dock?", "\"We were in a crowded line, and I was frustrated about waiting. {V} stumbled near the edge, and I think I bumped {V.him}.\""), .direct("Did you shove {V}?", "\"I put my hand out when {V} stepped in front of me. I don't remember a hard shove. {V} stumbled.\""), .direct("How are you coping with what happened?", "\"Horrible. A person died. I'm coping terribly with what happened.\""), .direct("What was the situation at the pantry?", "\"A long line that morning, and I had been waiting two hours with my family hungry. I was angry about people cutting ahead.\""), .direct("What happened with {V}?", "\"We argued at the edge of the dock, and I put my hand out to move {V} aside. {V} stepped back and fell.\""), .direct("What did you do?", "\"I yelled for help and went down to the lot. I stayed until paramedics came.\""), .cross("The camera shows a shove, doesn't it?", "\"It shows a push. I won't deny it. I didn't mean for {V} to fall.\""), .cross("{V} was seventy-three, wasn't {V.he}?", "\"Yes. I knew {V} was older. I shouldn't have touched anyone.\""), .cross("You were frustrated about waiting, weren't you?", "\"Yes. I'd waited a long time. It's no excuse.\""), .cross("You pushed {V}, didn't you?", "\"I put a hand on {V}'s chest. I did not mean for the fall.\""), .cross("You were standing at the edge of the dock because the line ran along it, weren't you?", "\"Yes, the line ran right along the edge with no rail, and people were pressed close together.\"")],
        openings: ("{V}, seventy-three, died after falling from a food pantry loading dock when, a volunteer says, {D} shoved {V} over a place in line. The dock camera shows the shove. The State will present the volunteer and the autopsy.", "Jurors will also see a crowded line at a hazardous dock, a pantry director who knows the dangers, and a stumble that no one meant."),
        closings: ("A volunteer who saw a shove, a dock with no rail, and a seventy-three year old who died from the fall. {D} was angry about waiting and put hands on someone at the edge.", "{D} says {V} stumbled, and the director saw only a struggle. The State has not proved a shove, and an edge with no rail is a danger no one should have faced."),
        timeline: [(0, "9 a.m.: the line."), (0, "9:10 a.m.: the dock."), (0, "9:11 a.m.: the fall."), (0, "10 a.m.: {V} dies.")],
        identified: "A volunteer.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .sympathetic,
        impact: "{V} was my parent, and my parent came to that pantry every week, even on the coldest days, to help others and take a bag of groceries home. It was a loading dock and a crowd, and an argument over a place in line. I miss the calls. Our family is broken.",
        doctrines: ["lesserIncluded"],
        genders: ["V": .male])

    static let ranchPipeAssaultV1 = SmallCases.make(
        key: "story.ranchPipeAssault",
        category: .violent,
        headlines: ["Cook Struck With Cast-Iron Skillet Over Unpaid Shifts", "Kitchen Fight Spills Into Alley"],
        law: "awdwik",
        threshold: 8,
        spec: "Assaulted {V} with a cast-iron skillet with intent to kill, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a line cook, was struck on the head with a skillet in an alley on {DATE} after demanding pay. {D}, the owner, was seen holding it. {DL} says {V} threw a bucket first.",
        state: [E(.statement, 3, "Dishwasher", "'{D} swung the skillet.'"), E(.physical, 3, "Skillet", "A skillet with blood.", .search), E(.forensic, 2, "Medical Report", "A skull fracture.")],
        defense: [E(.statement, 1, "Bucket", "{DL} says {V} threw a bucket first.")],
        role: "Dishwasher",
        exam: [.direct("What was the result?", "\"{V} had a skull fracture, according to the medical report. A skillet with blood on it was recovered.\""), .direct("What was the argument about?", "\"Pay. {D} owed {V} three weeks of pay, and {V} demanded it in the alley.\""), .direct("What did you see in the alley?", "\"{V} and {DL} were arguing near the back door late at night about unpaid wages. {DL} held a skillet, and {DL} swung it and hit {V} on the head.\""), .direct("What did {V} do before the swing?", "\"{V} demanded pay and shouted. {V} may have thrown something, but I did not see it clearly.\""), .direct("What happened next?", "\"{V} dropped to the ground and bled from the head. We called 911, and paramedics came within minutes.\""), .direct("What did you do after {V} fell in the alley?", "\"I ran to {V} and pressed a towel to the wound. I called 911 and stayed until the paramedics took over.\""), .cross("{D} says {V} threw a bucket first, doesn't {D.he}?", "\"I think a bucket was thrown. A bucket was dented, I noticed that.\""), .cross("Did you see {V} throw it?", "\"I did not see that. I only saw {DL} swing the skillet.\""), .cross("Did the defendant say anything after?", "\"{D.He} was upset and said things I do not remember.\""), .cross("A bucket was thrown, wasn't it?", "\"A dented bucket was nearby. I do not know who threw it.\""), .cross("{D} owed {V} three weeks of pay, didn't {D.he}?", "\"Yes. Everyone in the kitchen knew it.\"")],
        defenseRole: "Prep cook",
        defenseExam: [.direct("What did you see in the alley that day?", "\"A bucket thrown. I saw it fly through the air toward {D}, and it hit the wall behind {D.him}.\""), .direct("Who threw the bucket?", "\"I think {V}. It came from {V}'s direction, and {V} was standing right there.\""), .direct("What happened right after the bucket was thrown?", "\"{D.He} swung the skillet. It happened in a second, and then {V} was down on the ground.\""), .direct("What is your role?", "\"I am a prep cook at the same restaurant. I was in the back that night.\""), .direct("What did you hear?", "\"Shouting in the alley, then a loud clang. I ran out and saw {V} on the ground.\""), .direct("What did you see?", "\"I saw {DF} holding a skillet and a dented bucket near the door. I did not see who threw it.\""), .cross("Did you see {V} throw the bucket yourself?", "\"I think so, but I was looking at something else for a moment. I cannot be completely sure.\""), .cross("Was the bucket thrown at {D}'s head?", "\"It went in {D.his} direction. I did not see where it was aimed or whether it could have hit.\""), .cross("Did the defendant owe {V} pay for three weeks?", "\"Yes. I heard about that. Everyone in the kitchen knew {DF} was behind on pay.\""), .cross("You did not see the swing, did you?", "\"No. I saw the aftermath.\""), .cross("You knew about the unpaid wages, didn't you?", "\"Yes. It was a topic in the kitchen.\"")],
        theory: ("{D} struck a cook.", "A bucket."),
        allocution: "\"{V} threw a bucket at me first, and I swung the skillet without thinking. I owed three weeks of pay, and I told {V} I would pay when I could. It got heated in that alley. I lost my temper, and I'm sorry. I'll pay every dollar I owe.\"",
        truths: ("{DL} owed three weeks of pay.", "The bucket was dented."),
        defendant: [.direct("Did you hit {V} with the skillet?", "\"Yes. {V} threw a bucket at me first, and I swung the skillet without thinking. I was scared and angry.\""), .direct("Did you owe {V} pay?", "\"Yes. I owed three weeks. I was behind, and I told {V} I would pay when I could.\""), .direct("Why was the argument in the alley?", "\"{V} came out to demand the pay, and I went out to talk. It got heated quickly.\""), .direct("Did you ever pay what you owed?", "\"Part of it. I handed over some in cash and promised the rest, and I know it wasn't enough.\""), .direct("What happened that night?", "\"{V} came out to the alley and shouted that I owed money. {V} threw a bucket at me.\""), .direct("Why did you swing the skillet?", "\"I was frightened and hit {V} in a reflex. I did not mean to hurt that badly.\""), .cross("You owed {V} three weeks of pay, didn't you?", "\"Yes. I know I should have paid sooner. The restaurant was struggling.\""), .cross("The skillet was in your hand when you went out, wasn't it?", "\"I had been cooking. I did not go out meaning to use it.\""), .cross("{V} suffered a skull fracture. Do you accept responsibility?", "\"Yes. I am so sorry. I did not mean for that to happen.\""), .cross("You had the skillet in your hand before the bucket, didn't you?", "\"I had been cooking and carried it out. I should have put it down.\""), .cross("A skull fracture is a serious injury, isn't it?", "\"Yes. I am sick about it.\"")],
        openings: ("{V}, a line cook, was struck on the head with a skillet in an alley after demanding three weeks of unpaid pay. {D}, the owner, was seen holding the skillet, and {V} suffered a skull fracture.", "By the end of this trial, the proof will show that {V} threw a bucket first, that {D} swung the skillet in reaction, and that {DL} regrets what happened that night in the alley."),
        closings: ("Three weeks of unpaid pay, a skillet with blood on it, and a skull fracture. {D} was the owner and the one holding it.", "A thrown bucket and a skillet swung in a second of fear. The State must prove {D} was not reacting to an attack."),
        timeline: [(-21, "Pay goes unpaid."), (0, "11 p.m.: the demand."), (0, "11:10 p.m.: the swing."), (0, "11:40 p.m.: arrest.")],
        identified: "A witness and a skillet.",
        aggravating: ["The offense involved a weapon"],
        mood: .divided,
        impact: "I can't cook anymore. I spent my life in kitchens, and I was demanding the pay I earned when I was hit in the head with a skillet. I get dizzy standing at a stove. I lost my job and my confidence. Nobody should work for three weeks and get that.",
