        defense: [E(.statement, 1, "Job", "{DL} says it was a deposit on a side job.")],
        role: "SBI agent",
        exam: [.direct("What did your recording capture?", "\"An envelope passing to {D}, a county inspector, from a builder. It held $2,500.\""), .direct("What happened with the wiring inspection?", "\"A failed wiring inspection was passed that afternoon. {D.He} approved it after the envelope changed hands.\""), .direct("What did the builder tell you?", "\"That {D.he} said it would pass. The builder described the arrangement.\""), .direct("How did the investigation start?", "\"A builder complained that an inspector had asked for money to pass a failed wiring inspection. We set up a recorded meeting.\""), .direct("What does the recording show?", "\"An envelope passes from the builder to {D.him} at noon with $2,500 in it. {D.He} says something about taking care of it.\""), .direct("Who signed the inspection form?", "\"{D.He} did, at the bottom of the page. The date and time were written in {D.his} hand.\""), .cross("{D} says it was a deposit on a side job, doesn't {D.he}?", "\"Yes. {D.He} had done side jobs before. That is fair.\""), .cross("Did the envelope say anything about a job?", "\"It did not. It was cash in an envelope.\""), .cross("Was the inspection really failed?", "\"Yes. The earlier inspection showed a failure, and a pass came later.\""), .cross("{D} had done side work for builders before, hadn't {D.he}?", "\"Yes. Inspectors are allowed to do private work, but not for the jobs they inspect.\""), .cross("The builder said it would pass, didn't the builder?", "\"Yes, the builder told us {DL} said it would pass.\"")],
        defenseRole: "Inspector's supervisor",
        defenseExam: [.direct("Did {D} do side jobs outside the county work?", "\"Yes. {D} did electrical side jobs on weekends, and I knew about it. Many inspectors do.\""), .direct("Did the defendant do a side job for this builder?", "\"No. Not that I know. I would have approved it, and I did not.\""), .direct("Did the defendant approve the wiring that afternoon?", "\"Yes. {D.He} signed off on the wiring that afternoon, after the builder fixed some items.\""), .direct("What is your role?", "\"I supervise the county inspectors, and I reviewed this case after it was reported. I have supervised the inspection office for about nine years.\""), .direct("What do inspectors do about side work?", "\"They may do private work, but not on projects they inspect. We have a policy against it.\""), .direct("How did the defendant handle the job?", "\"{D.He} failed the wiring first, then passed it after the builder made repairs. The inspection paperwork for each visit is in proper order.\""), .cross("Did you review the second inspection?", "\"I looked at it. The wiring was changed, but the changes were small.\""), .cross("Would an inspector normally take cash from a builder?", "\"No. It would be a violation. I do not allow it.\""), .cross("Did the failed items get fixed before the pass?", "\"Some. I cannot say all.\""), .cross("Taking money from a builder is not allowed, is it?", "\"Not for a job under inspection.\""), .cross("You did not know about the deposit, did you?", "\"No. {D.He} did not report it.\"")],
        theory: ("{D} took a bribe.", "A job deposit."),
        allocution: "\"It was a deposit on a side job I had agreed to do for the builder, and the builder fixed the items. I rechecked and the wiring met code. I have done side jobs before, and many inspectors do. I misjudged how it would look, and I'm sorry to the county.\"",
        truths: ("{DL} approved the wiring that afternoon.", "{DL} had done side work before."),
        defendant: [.direct("Did you take $2,500 to pass the inspection?", "\"No. It was a deposit on a side job I had agreed to do for the builder. I did not take it to pass anything.\""), .direct("Why did you pass the wiring that afternoon?", "\"The builder fixed the items, and the wiring met code when I rechecked. I passed it honestly.\""), .direct("Do you do side work?", "\"Yes. I have done side jobs before. Many inspectors do, and my supervisor knows.\""), .direct("What is your job?", "\"I am a county building inspector who reviews wiring and framing. I have done it for fifteen years.\""), .direct("What was the money?", "\"A deposit on a side job for a deck at the builder's house. We agreed on a price and I took half.\""), .direct("What problems did you find on the first inspection?", "\"Some outlets were wired wrong and one panel had loose connections, so I failed the job and told the builder exactly what to fix.\""), .cross("The envelope was cash, not a check, wasn't it?", "\"Yes. It was cash. Many customers pay cash for side jobs.\""), .cross("You took the money from a builder whose project you were inspecting, didn't you?", "\"I did. That was a conflict, and I should have seen it. I feel awful about it.\""), .cross("The builder says you said it would pass. Is that wrong?", "\"I said I would look at it again. I did not promise a pass.\""), .cross("The deposit came on the day you passed the job, didn't it?", "\"Yes, and I see how close the timing is.\""), .cross("How much was in the envelope?", "\"Several hundred dollars in twenties. I counted it after I got home.\"")],
        openings: ("{D}, a county inspector, took $2,500 in an envelope from a builder on a recording, and approved a failed wiring inspection that same afternoon. The builder says {D.he} said it would pass.", "The defense witnesses will explain that {D} has done side work before, that the money was a deposit on a job, and that the wiring was fixed before the pass."),
        closings: ("Cash in an envelope, a failed inspection, and a pass that afternoon. An inspector who takes money from the builder under inspection has sold the signature.", "A deposit on a side job and wiring that was fixed before it was approved. The State must prove the money bought the pass, and it has not."),
        timeline: [(-3, "The failed inspection."), (0, "Noon: the envelope."), (0, "3 p.m.: the pass."), (30, "The sting.")],
        identified: "A recording.",
        aggravating: ["The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let lyingWitnessStandV1 = SmallCases.make(
