        state: [E(.document, 3, "Transcript", "'I saw the break.'"), E(.video, 3, "Doorbell Footage", "{D} at home."), E(.digital, 2, "Phone Location", "{DL} at home.")],
        defense: [E(.statement, 1, "Time", "{DL} says {D.he} misjudged the time.")],
        role: "Court reporter",
        exam: [.direct("What did {D} swear to in court?", "\"That {D} saw a defendant break a window. The transcript says, 'I saw the break.'\""), .direct("What does the defendant's phone show?", "\"{D.his} phone location was at home. It was nowhere near the window that was broken.\""), .direct("What did the defendant say on the stand?", "\"{D.He} swore to having seen a defendant break a window at about 10 p.m. The transcript has the words I saw the break.\""), .direct("What did the doorbell footage show?", "\"{DL} at home at that time, walking into the house. The footage is time-stamped.\""), .direct("What did the phone location show?", "\"{D.his} phone at home that evening. It did not move for hours.\""), .direct("What did you do when the doorbell footage came in?", "\"I played it next to the transcript and compared the times. The footage put {D.him} at home at the same minute {D.he} swore to have been on the street.\""), .cross("{D} says {D.he} misjudged the time, doesn't {D.he}?", "\"A similar break occurred the week before. I will agree that a mix-up is possible.\""), .cross("Did the defendant correct the testimony on the stand?", "\"No. {D.He} did not correct it. I recorded what was said.\""), .cross("Did you see the defendant testify?", "\"Yes. I recorded every word. I cannot judge who was telling the truth.\""), .cross("A similar break occurred the week before, didn't it?", "\"Yes, and {D.he} may have confused the two.\""), .cross("{D} told a friend the story, didn't {D.he}?", "\"Yes, before the trial. The friend repeated it to us.\"")],
        defenseRole: "Cousin",
        defenseExam: [.direct("Does {D} often mix up dates and times?", "\"Often. {D} has always had trouble keeping dates straight, and our family teases {DF} about it.\""), .direct("Was the defendant under oath when testifying?", "\"Yes. {DF} took the oath like anyone else. I was in the room.\""), .direct("How did the defendant seem when testifying?", "\"Nervous and unsure. {D.He} wanted to help and seemed to be trying hard to remember.\""), .direct("How do you know the defendant?", "\"We are cousins and talk several times a week. I heard about the window from {DF} the same week it happened.\""), .direct("What did the defendant say?", "\"That {D.he} saw the break from a window. {D.He} was convinced of it.\""), .direct("How is the defendant's memory?", "\"Usually good, but {D.he} mixes up days and times sometimes. That runs in our family, and we tease each other about it.\""), .cross("Did the defendant tell a friend about the window story before testifying?", "\"I heard that. I do not know what was said or how much was true.\""), .cross("Was the defendant at home when the window was broken?", "\"The footage says so. I was not with {D.him} that evening.\""), .cross("Are you related to the defendant?", "\"Yes. We are cousins. I know that matters.\""), .cross("You did not see it yourself, did you?", "\"No. I only heard {D.his} account.\""), .cross("{D} told the same story to you before trial, didn't {D.he}?", "\"Yes, more than once, in nearly the same words each time. That is why I believed it.\"")],
        theory: ("{D} lied under oath.", "A mistaken time."),
        allocution: "\"I believed what I said, but I confused two nights. I thought I saw it, and I was at home. I realized my mistake later. I told a friend the story before court and may have told it wrong. I was wrong, and I'm sorry to the court and to the defendant.\"",
        truths: ("{DL} had told a friend the window story.", "A similar break occurred the week before."),
        defendant: [.direct("Did you see the window break?", "\"I thought I did. I believed what I said, but I mixed up the time. A similar break happened the week before.\""), .direct("Why was your testimony wrong?", "\"I confused two nights. I thought I saw it, but I was at home. I realized that later.\""), .direct("Did you tell a friend the window story?", "\"Yes. I told a friend the story before court. I may have told it wrong.\""), .direct("Why did you testify?", "\"I thought I had seen the break and wanted to help. I had told a friend about it.\""), .direct("How sure were you?", "\"I was sure of what I saw, but I may have had the wrong night. I may have mixed up the time.\""), .direct("What did you do when shown the footage?", "\"I told the court I may have been wrong about the time. I did not mean to lie.\""), .cross("The doorbell footage puts you inside your home, doesn't it?", "\"Yes. I was home. I know it contradicts what I said.\""), .cross("Your phone was at home too, wasn't it?", "\"Yes. I was not near the window. I should not have testified.\""), .cross("You swore under oath to something false, didn't you?", "\"I swore to what I believed. I was wrong, and I apologize.\""), .cross("You swore you saw the break, didn't you?", "\"Yes. I believed it at the moment.\""), .cross("Your phone and doorbell put you at home, don't they?", "\"Yes. I see that now.\"")],
        openings: ("{D} swore under oath that {D.he} saw a defendant break a window, but doorbell footage and {D.his} phone place {DL} inside {D.his} own home at the time. {DL} had told a friend the story first.", "Listen for the defense evidence, which will show that {D} confused two similar breaks a week apart, honestly believed the testimony, and never meant to lie to the court."),
        closings: ("A sworn statement, a doorbell camera at {D}'s home, and a phone that agrees. {D.He} swore to something {D.he} could not have seen.", "A cousin who mixes up dates and a similar break the week before. The State must prove {D} knew the testimony was false, and confusion is not perjury."),
        timeline: [(-7, "An earlier break."), (0, "Trial day: the oath."), (7, "The footage."), (30, "{DL} is charged.")],
        identified: "Doorbell footage.",
        mood: .divided,
        doctrines: ["mistakeOfFact"])

