        defense: [E(.statement, 1, "Old Login", "{DL} says anyone could have used it."), E(.statement, 1, "Shared Connection", "{DL} shares a connection with neighbors.")],
        role: "Dental office manager",
        exam: [.direct("What happened to your scheduling system?", "\"It locked up just as the first patients arrived. A message demanded $6,000 and warned that records would be wiped.\""), .direct("What did the message trace to?", "\"An internet address assigned to {D}'s home. We never disabled {D.his} login after the firing.\""), .direct("How long was the system down?", "\"About two hours. Staff wrote everything on paper until the vendor got it running again.\""), .direct("What did the access log show?", "\"The lock was started with a login that belonged to {D.him}, a receptionist we fired a month earlier. The login came from an address tied to {D.his} home.\""), .direct("Why was the old login still active?", "\"We never disabled it, which was our mistake. It stayed active after {D.he} left.\""), .direct("What did you do to get the scheduling system running again?", "\"We called our vendor and restored from a backup. It took until noon, so we rescheduled the morning's patients and lost a day of revenue.\""), .cross("{D} says someone used {D.his} old login, doesn't {D.he}?", "\"We never disabled it, so it is possible. That is fair.\""), .cross("Did the defendant ask anyone whether the login still worked?", "\"Yes. {D.He} asked a coworker whether it still worked.\""), .cross("Did the defendant search for how to lock a database?", "\"I understand so. A search appears in the records.\""), .cross("Anyone could have used the old login, couldn't they?", "\"Anyone who knew it could. {D.He} shares a connection with neighbors.\""), .cross("The login was not disabled, was it?", "\"No. That is a failure on our side, and I admit it.\"")],
        theory: ("{D} locked an office's records and demanded ransom.", "A former employee whose old login was used."),
        allocution: "\"Someone used my old login, which the office never disabled, and I did not do this. I did once want to retrieve a personal file, and I was curious after reading about an attack. I'm sorry for the trouble to the dental office. I'll stay away from it.\"",
        truths: ("{DL} had asked a coworker whether the login still worked.", "{DL} searched online for how to 'lock a database' the week before."),
        defendant: [.direct("Did you lock the dental office's system?", "\"No. I did not. Someone used my old login, which the office never disabled.\""), .direct("Why did you ask a coworker whether the login still worked?", "\"I wanted to retrieve a personal file. I did not use it for anything else.\""), .direct("What about your search for how to lock a database?", "\"I was curious after reading about an attack. I did not do it.\""), .direct("What was your relationship with the office?", "\"I worked as a receptionist for three years and was let go a month earlier. I was angry about it.\""), .direct("What did you do with the login?", "\"I asked a coworker whether it still worked. I was curious and did not mean harm.\""), .direct("What could your login do inside the office system?", "\"It let me open patient schedules and the billing screens, and I assume someone using it could reach more than I ever did.\""), .cross("The message traced to your home address, didn't it?", "\"Yes. But someone could have used my network. I do not know.\""), .cross("You were fired a month earlier, weren't you?", "\"Yes. I was angry. I would not take it out on patients.\""), .cross("Your login was used to start the lock. How do you explain that?", "\"I cannot. The office never disabled it.\""), .cross("You searched how to lock a database the week before, didn't you?", "\"Yes. I know the timing looks bad.\""), .cross("Who else had access to your home network?", "\"My roommate and a couple of friends who visited. I never changed the password.\"")],
        openings: ("A dental office's scheduling system locked up as patients arrived, with a message demanding $6,000 or records would be wiped. The lock was started with the old login of {D}, a receptionist fired a month earlier, from {D.his} home address.", "Weigh the defense proof, which will show that the office never disabled the login, that anyone could have used it, and that {D} did not launch the attack."),
        closings: ("A lockup demanding $6,000, a login that belonged to {D}, an address that traces to {D.his} home, and a search for how to lock a database. The attack came from {D.him}.", "A login the office never disabled and a home network that others could reach. The State must prove {D} was the one at the keyboard."),
        timeline: [(-30, "{D} is fired."), (-7, "{D} searches how to lock a database."), (0, "The system locks."), (0, "The demand arrives."), (1, "The access log is traced.")],
        identified: "An access log.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let churchFireFormerV1 = SmallCases.make(
        key: "story.churchFireFormer",
        category: .violent,
        headlines: ["Synagogue Annex Burned at Night; Dismissed Caretaker Questioned", "Accelerant in the Kitchen"],
        law: "burningBuildings",
        threshold: 8,
        spec: "Willfully and maliciously burned an annex owned by {V}, a congregation, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A congregation's annex burned on {DATE}. Accelerant was found in the kitchen. {D}, a dismissed caretaker, was seen nearby. {DL} says {D.he} was walking a dog.",
        state: [E(.forensic, 3, "Fire Report", "Accelerant in the kitchen."), E(.video, 2, "Street Camera", "{D} passes at midnight."), E(.statement, 2, "Rabbi", "{D} was upset at dismissal.")],
        defense: [E(.statement, 1, "Dog Walk", "{DL} says {D.he} was walking a dog.")],
        role: "Fire marshal",
        exam: [.direct("What did you find at the congregation's annex on {DATE}?", "\"It burned, and I found accelerant in the kitchen.\""), .direct("What did you find in the annex after the fire?", "\"A kitchen with heavy burn patterns on the floor and traces of an accelerant. The fire started low and spread up the wall to the main hall.\""), .direct("What does the street camera show?", "\"It shows {D} walking past the annex at midnight with a dog on a leash, about an hour before the fire. {D.He} stops and looks at the building.\""), .direct("What did the rabbi tell you?", "\"{D.He} had been dismissed as caretaker weeks earlier and was upset. {D.He} still had a spare key, which was not returned.\""), .direct("What did the congregation lose in the fire?", "\"The annex held our classroom, our kitchen, and the records of the past decade. Most of it was destroyed, and the sanctuary had smoke damage.\""), .direct("What did you do when the alarm company called you that night?", "\"I drove straight over. The annex was already in flames, and the fire crews were pulling hose. I could do nothing but stand and watch.\""), .cross("{DL} says {D.he} was walking a dog, doesn't {D.he}?", "\"A neighbor says {DL} walks a dog most nights. I can't say it wasn't true.\""), .cross("Did anyone see {DL} at the annex?", "\"No. The camera shows {DL} passing. I have no witness at the building.\""), .cross("Was the annex locked?", "\"I believe so. I can't say who had keys.\""), .cross("{D} was walking a dog, wasn't {D.he}?", "\"The camera shows a dog on a leash. The dog is a known walker in the area.\""), .cross("No one saw the defendant go inside, did they?", "\"No. The camera shows {DL} passing and no entrance.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("How do you know {D}?", "\"I live on the street and often see {D} walking the dog in the evening. We chat about the weather and the neighborhood.\""), .direct("What did you see that night?", "\"{D.He} walked by with the dog around midnight, as usual. I was up late and saw the dog sniffing at hedges.\""), .direct("Does the dog belong to the defendant?", "\"No, it belongs to a neighbor who asked {DF} to walk it. {DF} does this for a few families.\""), .direct("How did the defendant seem?", "\"Normal and calm. {D.He} waved and kept walking toward the park.\""), .direct("What did you do when the fire started?", "\"I smelled smoke at about one and called 911. I saw flames in the annex window from my house.\""), .direct("What did you tell deputies about the defendant?", "\"That I saw {D.him} with the dog earlier and nothing else. I did not see anyone go in.\""), .cross("You did not watch the defendant the whole time, did you?", "\"No. I saw {DF} pass and then went back inside.\""), .cross("You do not know what the defendant did after the corner, do you?", "\"No. {D.He} turned toward the park.\""), .cross("You cannot say whether the defendant still had the key, can you?", "\"No. I never knew about the key.\""), .cross("An hour passed between the walk and the fire, didn't it?", "\"About an hour, by my watch. I went home and ate, and then I heard the sirens.\""), .cross("You do not know who started the fire, do you?", "\"No. I do not know who started the fire.\"")],
        theory: ("{D} burned an annex.", "A dog walk."),
        allocution: "\"I was walking a neighbor's dog, which I do most nights, and the route passes that building. I looked at it because I had worked there six years, and I was hurt and angry about being let go. I never touched it. I'm sorry for the congregation.\"",
        truths: ("{DL} had a spare key.", "The dog is a known walker."),
        defendant: [.direct("Why were you outside the annex at midnight?", "\"I was walking a neighbor's dog, which I do most nights. The route passes the annex on the way to the park.\""), .direct("Why did you stop?", "\"I looked at the building because I had worked there for six years. I missed the place.\""), .direct("How did you feel about the dismissal?", "\"Hurt and angry. I had given years to the congregation, and I was let go without a conversation.\""), .direct("Did you have a key?", "\"Yes, a spare I forgot to return. I never used it after I left.\""), .direct("Did you go inside?", "\"No. I stayed on the sidewalk and walked on. I did not go near the kitchen door.\""), .direct("What did you do when you heard about the fire?", "\"I was shocked. I told deputies where I had been and offered my phone.\""), .cross("You were upset about the dismissal, weren't you?", "\"Yes, and I will not hide it. That does not mean I set a fire.\""), .cross("You had a spare key, didn't you?", "\"Yes, but I did not use it that night.\""), .cross("You were outside the building an hour before the fire, weren't you?", "\"Yes, on the sidewalk, for a minute or two.\""), .cross("The fire started in the kitchen, didn't it?", "\"So I was told. I never went in.\""), .cross("Nobody else saw you with the dog, did they?", "\"The camera did, and neighbors know me.\"")],
        openings: ("A congregation's annex burned, with accelerant in the kitchen. {D}, a dismissed caretaker who was upset, passed on the street camera at midnight. The State will present the fire marshal and the rabbi.", "The defense will present a nightly dog walk past the annex, a neighbor who saw it, and no witness who saw {D} at the building."),
        closings: ("Accelerant in the kitchen, a dismissed caretaker with a spare key, and {D} on camera outside the annex an hour before the fire. The congregation lost a building that held its kitchen and classrooms.", "A dog walk at midnight is not an arson. The State has not proved {D} entered the annex, and a spare key and a grudge are not enough to prove a fire."),
        timeline: [(-14, "The dismissal."), (0, "Midnight: {DL} passes."), (0, "1 a.m.: the fire."), (0, "2 a.m.: crews.")],
        identified: "A camera.",
        mood: .divided,
        impact: "Our school wing is gone. The children who learned to read in those rooms now meet in borrowed space across town. We found the kitchen where the fire began. Years of work and love went into that annex, and the congregation is still grieving.",
        doctrines: ["burdenOfProof"])

    static let tireSparePillsV1 = SmallCases.make(
        key: "story.tireSparePills",
        category: .drugs,
        headlines: ["Traffic Stop Finds Fentanyl Pills in Child Car Seat Base", "K-9 Alerts at the Rear Door"],
        law: "traffickingOpioid",
        threshold: 8,
        spec: "Trafficked in opium or opioids by possession of 4 grams or more, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A trooper stopped {D} on {DATE} and a K-9 alerted at the rear door. A car seat base held 2,000 fentanyl pills. {DL} says the car belonged to a sister.",
        state: [E(.forensic, 3, "Lab Report", "2,000 fentanyl pills."), E(.physical, 3, "Car Seat Base", "Pills packed inside.", .search), E(.digital, 2, "Phone Messages", "'Delivering tonight.'")],
        defense: [E(.statement, 1, "Sister", "{DL} says the car belonged to a sister.")],
        role: "Highway Patrol trooper",
        exam: [.direct("Why did you stop {D}?", "\"I stopped {D} on the highway, and my K-9 alerted at the rear door. A search found 2,000 fentanyl pills inside a car seat base.\""), .direct("What did the lab confirm?", "\"The lab report confirms the pills are fentanyl. They were packed inside the base.\""), .direct("What did you find on the defendant's phone?", "\"A message that said, 'Delivering tonight.' {DL} also carried $3,000 in cash.\""), .direct("How long did the stop last before the search?", "\"Not long. The dog walked around the car right away and alerted at the rear door, and then I searched.\""), .direct("What happened with the K-9?", "\"The dog alerted at the rear door. A search found a car seat base holding about 2,000 pills in a sealed bag.\""), .direct("What did the lab say?", "\"The pills were fentanyl. We also found $3,000 in cash on {DL}.\""), .cross("{D} says the car belonged to a sibling, doesn't {D.he}?", "\"Yes. The owner confirmed lending the car. That is accurate.\""), .cross("Did the defendant seem to know about the pills?", "\"{D.He} said no. I could not read {D.his} mind.\""), .cross("Was the car seat base visible?", "\"It was in the back seat. Nothing looked odd from outside.\""), .cross("Who is the owner of the car?", "\"A sibling of the defendant. The registration has the sibling's name and address.\""), .cross("{D} did not run, did {D.he}?", "\"No. {D.He} cooperated and did not run.\"")],
        defenseRole: "Car owner",
        defenseExam: [.direct("Did you lend your car to {D}?", "\"Yes. I lent the car for a few days, and {D} came to pick it up.\""), .direct("Did you know pills were in the car seat base?", "\"No. I did not know. I had a car seat base in the car for my own child.\""), .direct("Did you lend it to carry pills?", "\"No. Never. I would not lend my car for that.\""), .direct("What is your connection to the defendant?", "\"I am {D.his} sibling and I own the car. I lent it to {D.him} for a few days.\""), .direct("What did you tell the defendant?", "\"To take care of it and bring it back by the weekend. I did not mention the car seat.\""), .direct("Whose car seat base was it?", "\"Mine, from when my child was small. It had been in the car for a while.\""), .cross("When was the last time you looked in the car seat base?", "\"A while ago. I did not look in it before lending the car.\""), .cross("Who else has used the car recently?", "\"A few people. I lend it sometimes.\""), .cross("Do you know about the message 'Delivering tonight'?", "\"No. I do not know what that means.\""), .cross("You did not check the base before lending, did you?", "\"No. I had not touched it in months.\""), .cross("You do not know how the pills got in, do you?", "\"No. I was shocked when I heard.\"")],
        theory: ("{D} trafficked fentanyl.", "A sister's car."),
        allocution: "\"I borrowed the car from a relative and never looked in the car seat base. I was carrying pay and supply money for a job I had lined up. I made a bad choice in driving that car without checking, and I'm ready to deal with it.\"",
        truths: ("{DL} carried $3,000 cash.", "The sister confirmed lending the car."),
        defendant: [.direct("Did you know there were pills in the car seat base?", "\"No. I borrowed the car from a relative, and I did not look in the car seat base.\""), .direct("Why did you have $3,000 in cash?", "\"It was for a job I had lined up. I was carrying pay and supplies money.\""), .direct("What did your 'Delivering tonight' message mean?", "\"I was delivering items for a job. I did not mean pills.\""), .direct("How did you come to be driving that car?", "\"It belonged to a sibling, who lent it to me for a few days, and I had no idea what was in it.\""), .direct("What about the cash?", "\"$3,000 was money I had saved for rent. I carry cash because I do not have a bank account.\""), .direct("What about the messages?", "\"A text saying delivering tonight was about a furniture delivery. I was not talking about pills.\""), .cross("2,000 fentanyl pills were in the car you were driving, weren't they?", "\"Yes. I did not know. I still do not know how they got there.\""), .cross("$3,000 in cash and a message about delivering. How is that not a delivery?", "\"It was a different kind of delivery. It sounds bad, I know.\""), .cross("The car owner confirms lending it to you. Did you check the car?", "\"No. I trusted the owner.\""), .cross("The pills were in a car seat base, weren't they?", "\"Yes. Nothing in the seat looked unusual to me.\""), .cross("You carried $3,000 in cash, didn't you?", "\"Yes. I know that looks bad.\"")],
        openings: ("A trooper stopped {D}, a K-9 alerted at the rear door, and a search found 2,000 fentanyl pills in a car seat base. {D.He} carried $3,000 in cash, and a phone message said, 'Delivering tonight.'", "The defense evidence will establish that the car belonged to a relative who confirms lending it, and that {D} never knew the pills were there."),
        closings: ("Two thousand fentanyl pills, $3,000 in cash, and a message about delivering tonight. A driver answers for what is in the car.", "A borrowed car, a car seat base, and a relative who confirms the loan. The State must prove {D} knew the pills were there."),
        timeline: [(0, "1 p.m.: the stop."), (0, "1:15 p.m.: the K-9."), (0, "1:40 p.m.: the search."), (0, "2 p.m.: arrest.")],
        identified: "A search.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["searchSeizure", "mistakeOfFact"])

    static let pawnStrawBuyV1 = SmallCases.make(
        key: "story.pawnStrawBuy",
        category: .violent,
        headlines: ["Buyer Took Three Rifles at Gun Show for Felon Brother", "Texts List Calibers Wanted"],
