        threshold: 8,
        spec: "Aided a person with a felony conviction in possessing a firearm, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} bought three rifles at a gun show on {DATE}. Texts showed {DL}'s brother, a felon, choosing calibers. {DL} says they were gifts.",
        state: [E(.digital, 3, "Text Messages", "The brother lists calibers."), E(.document, 3, "Bills of Sale", "{D} purchased three rifles."), E(.statement, 2, "Dealer", "The brother stayed at the door.")],
        defense: [E(.statement, 1, "Gifts", "{DL} says the rifles were gifts.")],
        role: "Gun show dealer",
        exam: [.direct("What did {D} buy at your gun show table?", "\"Three rifles. The bills of sale show {D} as the purchaser, and {D.he} passed the background check without trouble.\""), .direct("What did the text messages between the defendant and the sibling show?", "\"{D.his} sibling, a felon, listing calibers to choose. The texts tell {D.he} which rifles the sibling wanted bought.\""), .direct("Where was the sibling during the purchase at your table?", "\"At the door of the hall. The sibling did not come to my table, and I did not speak with that person.\""), .direct("What happened at your table?", "\"{D.He} bought three rifles on a busy afternoon and paid by debit card. Another person stood near the door the whole time.\""), .direct("Who was at the door?", "\"{D.his} sibling, who is a convicted felon and could not legally buy a gun.\""), .direct("What did the texts show?", "\"The sibling listing calibers and brands for {D.him} to buy. The messages came before the show.\""), .cross("{D} says they were gifts, doesn't {D.he}?", "\"Yes. And {D.he} paid by debit card, I understand. A debit card is not how people hide a purchase.\""), .cross("Was the defendant legally allowed to buy rifles at that show?", "\"Yes. {D.He} passed the check and had no record that would bar a purchase. Everything was in order.\""), .cross("Did the defendant seem to know about the sibling's record when buying?", "\"I do not know. {D.He} did not say anything about it, and I did not ask {D.him} about the sibling.\""), .cross("{D} filled out the paperwork honestly in {D}'s own name, didn't {D.he}?", "\"Yes. The bills of sale are in {D.his} name.\""), .cross("The sibling did not touch the guns at your table, did the sibling?", "\"The sibling stayed back, and I did not see any handling of the rifles.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("Does {D} hunt as a hobby or for sport?", "\"Yes. {D} hunts every season, and I have been in the woods with {D.him} for many trips over the years.\""), .direct("Would the defendant buy three rifles at one time?", "\"Maybe. {DF} enjoys buying guns, and I have seen {DF} buy two at a time before, for family and friends.\""), .direct("Did the defendant ever mention buying a rifle for someone else?", "\"No. I never heard that. {D.He} talked about gifts for family members who like to hunt, not anything beyond that.\""), .direct("How do you know the defendant?", "\"We are friends and have gone to shows together. I was at the show that day.\""), .direct("What did the defendant tell you about the rifles?", "\"That they were gifts for the family. {D.He} was excited.\""), .direct("What did you see?", "\"{D.He} picked three rifles and paid. A person stood by the door.\""), .cross("Did you know the defendant's sibling who texted the calibers?", "\"I have met the sibling a few times. I know that the sibling has some kind of a record.\""), .cross("Did the defendant tell you about this purchase at the gun show?", "\"No. I heard about it only after the fact. {D.He} did not mention it to me before or during.\""), .cross("Have you seen the rifles that the defendant bought that day?", "\"No. I do not know where they went after the show, and I did not ask about them afterward.\""), .cross("You did not know the person at the door was a felon, did you?", "\"No. I learned later. I didn't know the person at the door was a felon.\""), .cross("You did not hear the caliber texts, did you?", "\"No. I did not hear the caliber texts.\"")],
        theory: ("{D} bought guns for a felon.", "Gifts."),
        allocution: "\"I bought those rifles for myself and for a few friends, and I never meant for a prohibited person to have any. I wanted to give gifts to family members. I'm not proud of it. I should have thought about who was choosing, and I'll never buy another.\"",
        truths: ("The rifles were found at the brother's home.", "{DL} paid by debit card."),
        defendant: [.direct("Who were the rifles for?", "\"For myself and for a few friends. I did not buy them for a prohibited person.\""), .direct("Why were they found at your sibling's home?", "\"I was visiting and left them there. I did not mean for the sibling to keep them.\""), .direct("Why did you buy three rifles?", "\"They were gifts for family members. I wanted to give my sibling and others something for the holidays.\""), .direct("What did your sibling say?", "\"The sibling told me what was liked, and I bought them. I did not realize I was breaking a law.\""), .direct("Where did the rifles end up?", "\"Deputies found them at my sibling's home, because I handed them over.\""), .direct("What did you do at the gun show once the rifles were chosen?", "\"I paid at the counter and carried them to my car. I told the dealer they were gifts, and I should have thought harder about who they were for.\""), .cross("Your sibling, a felon, chose the calibers by text, didn't the sibling?", "\"The sibling texted calibers and likes guns. That does not mean they were for the sibling.\""), .cross("You paid by debit card. Whose money was it?", "\"Mine. I paid with my own debit card for what I bought.\""), .cross("A felon cannot own rifles. Did you know that?", "\"Yes. I know. I would never give one to the sibling.\""), .cross("You did not take the rifles back to your own home after you visited, did you?", "\"No. I left them at the sibling's home when I visited and did not carry them back with me, and that was a mistake.\""), .cross("You paid with your own debit card, didn't you?", "\"Yes. It was my money.\"")],
        openings: ("{D} bought three rifles at a gun show while {D.his} sibling, a felon, stayed at the door and texted calibers. The rifles were later found at the sibling's home.", "By the end of this trial, the proof will show that {D} paid with a personal debit card, bought gifts for hunting, and left the rifles at the sibling's home by mistake."),
        closings: ("A felon chose the calibers by text, {D} bought three rifles, and they ended up at the felon's home. That is a straw purchase, plain and simple.", "A hunter with a clean record who paid with a debit card and bought gifts. The State must prove {D} bought them for a prohibited person."),
        timeline: [(-7, "The texts."), (0, "Noon: the buy."), (1, "The search."), (2, "{DL} is charged.")],
        identified: "Bills of sale.",
        aggravating: ["The offense involved a firearm"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let forgedDeedLotV1 = SmallCases.make(
        key: "story.forgedDeedLot",
        category: .whiteCollar,
        headlines: ["Man Forged Power of Attorney to Sell Aunt's Farm", "Notary Seal Was a Copy"],
        law: "forgery",
        threshold: 8,
        spec: "Forged a power of attorney of {V} with intent to defraud, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} used a forged power of attorney on {DATE} to sell {V}'s farm for $190,000. The notary seal was a copy. {DL} says an attorney prepared it.",
        state: [E(.document, 3, "Power of Attorney", "A forged signature and seal."), E(.document, 3, "Sale Record", "{D} received $190,000."), E(.forensic, 2, "Handwriting Report", "Not {V}'s.")],
        defense: [E(.statement, 1, "Attorney", "{DL} says an attorney prepared it.")],
        role: "Register of deeds clerk",
        exam: [.direct("What did you review about the sale of {V}'s farm?", "\"A power of attorney with a forged signature and a copied notary seal, used to sell the farm for $190,000.\""), .direct("Who received the money?", "\"{D}. The sale record shows {DL} received $190,000.\""), .direct("What did the handwriting report say?", "\"The signature is not {V}'s. That's in the report.\""), .direct("What did you receive at the register of deeds?", "\"A power of attorney recorded to sell {V}'s farm. The signature and notary seal looked off, and the seal was a copy.\""), .direct("What did the sale record show?", "\"The farm sold for $190,000, and the proceeds went to {D.him}. The sale closed within weeks.\""), .direct("How was the forgery detected?", "\"{V} found out after being told the farm was sold. A handwriting report found the signature was not {V}'s.\""), .cross("{DL} says an attorney prepared it, doesn't {D.he}?", "\"I can't say who prepared it. I only know who recorded it.\""), .cross("Did you check the notary seal?", "\"We look at the face of the document. The copy looked real. We can't verify each seal.\""), .cross("Did {DL} act oddly at your counter?", "\"No. {D.He} was polite and ordinary.\""), .cross("An attorney prepared the power of attorney, according to {D}, correct?", "\"That is {D.his} claim. The attorney's phone reached a real office.\""), .cross("You recorded it without question, didn't you?", "\"We record what is presented if it looks complete. It looked complete.\"")],
        defenseRole: "Closing agent",
        defenseExam: [.direct("What is your role?", "\"I am a closing agent who handles real estate sales and title work for buyers and sellers. I handled this farm sale from start to finish.\""), .direct("How did the sale come to you?", "\"{D} brought a power of attorney from an attorney's office and instructions to sell the farm. It looked ordinary.\""), .direct("What did you check?", "\"The seal and signature on the document and the buyer's funds. I did not call {V} directly because a power of attorney lets someone else sign.\""), .direct("What did you notice about the notary seal?", "\"It looked like a standard stamp. I did not examine it under magnification.\""), .direct("How was the money handled?", "\"The buyer's funds came to our trust account, and we sent proceeds to {D.him}. We kept a record.\""), .direct("What happened when {V} complained?", "\"We checked and learned the seal was a copy. We reported it.\""), .cross("You did not contact {V} before the sale, did you?", "\"No. A power of attorney lets someone else sign.\""), .cross("You relied on the attorney's name, didn't you?", "\"Yes. It was a real office.\""), .cross("The notary seal was a copy, wasn't it?", "\"Yes. We did not catch it.\""), .cross("You sent $190,000 to {D}, didn't you?", "\"Yes. I sent $190,000 to {D.him}, less fees.\""), .cross("You cannot say who forged the signature, can you?", "\"No. I only know it was not caught.\"")],
        theory: ("{D} forged a power of attorney.", "An attorney."),
        allocution: "\"An attorney prepared that paperwork, and I took it to be recorded and used it to sell the farm. I never saw {V} sign. I trusted the paperwork. I received the proceeds because I thought I was entitled to handle it. I was desperate, and I'm sorry.\"",
        truths: ("{DL} owed back taxes.", "The attorney's phone reached a real office."),
        defendant: [.direct("Where did the power of attorney come from?", "\"An attorney prepared it. I took it to be recorded and used it to sell the farm.\""), .direct("Did you forge {V}'s signature?", "\"No. I never saw {V} sign. I trusted the attorney and the paperwork.\""), .direct("What did you do with the $190,000?", "\"I received it from the sale. I thought I was entitled to handle it. I didn't know it was forged.\""), .direct("How did you come to sell the farm?", "\"{V} had asked me to handle the sale, and an attorney prepared the power of attorney. I trusted the attorney.\""), .direct("Why did you need the money?", "\"I owed back taxes and the sale helped. I paid some of it to the county.\""), .direct("What did you know about the signature?", "\"I thought {V} signed it. The attorney told me it was ready.\""), .cross("You presented the document, didn't you?", "\"Yes. I did. I thought it was valid.\""), .cross("You received $190,000, didn't you?", "\"Yes. It was a big sum. I should have questioned it.\""), .cross("You can't name the attorney, can you?", "\"I have a name and a phone number. The number reached an office, but no one there would say they had prepared it, and I know how that looks.\""), .cross("The handwriting report says the signature is not {V}'s, doesn't it?", "\"So I have learned. I did not do it.\""), .cross("You never asked {V} to confirm the sale, did you?", "\"No. I assumed it had been taken care of. I should have called {V} and heard it directly before I signed anything.\"")],
        openings: ("{D} used a forged power of attorney with a copied notary seal to sell {V}'s farm for $190,000 and received the money. A handwriting report says the signature is not {V}'s. The State will show the record and the report.", "The defense will point you to a person who presented a document that an attorney prepared, used real ID, and relied on professionals. Listen closely to the witnesses."),
        closings: ("A forged power of attorney, a copied notary seal, and a $190,000 farm sale with the money going to {D}. {V} lost a farm that had been in the family, and the paper that took it was a lie.", "An attorney prepared the document, according to {D}, and a phone reached a real office. The State has not proved {DL} knew the signature was forged, and an owed tax bill is not proof of forgery."),
        timeline: [(-30, "The farm is listed."), (0, "The power is recorded."), (14, "The sale closes."), (60, "{V} finds out.")],
        identified: "A power of attorney.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "It was {V.his} family's land. Four generations farmed it, and {V} came to my office with a folder of deeds to prove it. Now a stranger holds the title and {V.he} doesn't know where to turn. I stamped those papers every week and never imagined this would happen.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let cafeBurnedForInsuranceV1 = SmallCases.make(
        key: "story.cafeBurnedForInsurance",
        category: .whiteCollar,
        headlines: ["Furniture Store Owner Burned Showroom for Insurance", "Candles Left on a Timer"],
        law: "insuranceFraud",
        threshold: 8,
        spec: "Presented a false claim to an insurer after willfully burning an insured building, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A furniture showroom burned on {DATE}. {D}, the owner, filed a $400,000 claim. Investigators found a candle-and-timer device. {DL} says an electrical fire started it.",
        state: [E(.forensic, 3, "Fire Report", "A timer device found."), E(.document, 3, "Financial Records", "$150,000 in debt."), E(.video, 2, "Street Camera", "{D} leaves at 7 p.m.")],
        defense: [E(.statement, 1, "Electrical", "{DL} says an electrical fire started it.")],
        role: "Fire marshal",
        exam: [.direct("Tell us about the fire and how you investigated.", "\"I'm the fire marshal. A furniture showroom burned on the night in question, and I examined the origin and the debris.\""), .direct("What did you find at the showroom on {DATE}?", "\"It burned, and I found a candle-and-timer device at the point of origin.\""), .direct("What does the street camera show?", "\"It shows {D} leaving at 7 p.m. The fire started later that night.\""), .direct("What did the fire marshal conclude?", "\"That the fire was set deliberately. The device and the pattern on the floor both pointed to it.\""), .direct("What did the financial records show?", "\"The owner, {DL}, owed about $150,000 and had raised the coverage a month earlier. The claim was $400,000.\""), .direct("How did you find the device in the showroom?", "\"It was under a sofa in the back with a burned candle stub and a kitchen timer. The timer's wiring ran to a small battery.\""), .cross("{DL} says an electrical fire started it, doesn't {D.he}?", "\"I found a timer device, which isn't electrical wiring.\""), .cross("Was there any wiring concern?", "\"Some wiring items. They don't explain a candle and a timer.\""), .cross("Did anyone see {DL} set the device?", "\"No. This is a circumstantial case.\""), .cross("Was there any wiring problem in the building?", "\"An inspector flagged some wiring the year before. I examined it and found no sign it started the fire.\""), .cross("Can you say who placed the device?", "\"No. I can only say it was placed.\"")],
        defenseRole: "Fire inspector",
        defenseExam: [.direct("Please tell us about your inspection.", "\"I'm a fire inspector. I inspected the showroom a year before the fire.\""), .direct("Do you inspect buildings?", "\"Yes. I'm a fire inspector. I've been in the showroom.\""), .direct("What did you note?", "\"Some wiring items. Nothing urgent, but several things that should have been fixed within the year, and I listed each one.\""), .direct("Did the showroom pass?", "\"Mostly. It passed the main points but had several items that needed attention before the next inspection.\""), .direct("Did you tell {D}?", "\"Yes. I gave {D} a copy of the report and told {D.him} to have an electrician fix every item on the list.\""), .direct("What did you tell the defendant after the inspection last year?", "\"I told {DF} the wiring in the back room needed to be redone and gave a written list. I never heard that anything was done.\""), .cross("Could wiring cause a candle and timer?", "\"No. A candle with a timer is a device someone placed, and wiring cannot make that on its own.\""), .cross("Did you see the device?", "\"No. I only inspected the building a year before the fire, and I wasn't at the scene.\""), .cross("Did you flag the wiring in writing?", "\"Yes. I wrote it in my report and gave {DF} a copy to keep.\""), .cross("You can't say whether anything changed in the building during that year, can you?", "\"No. I wasn't there after my inspection, so I can't say what was changed or added.\""), .cross("A flagged wire does not mean the wire caused this fire, does it?", "\"No. It means there was a risk. I cannot tell you whether the wiring was involved here without examining the burn pattern.\"")],
        theory: ("{D} burned a showroom.", "An electrical fire."),
        allocution: "\"It was my livelihood, and I never saw any candle or timer. I owned that showroom for twelve years, and it was my life's work. I'd never destroy it. I'm sorry to everyone I let down. I'll repay what I can.\"",
        truths: ("{DL} raised coverage a month earlier.", "An inspector flagged wiring last year."),
        defendant: [.direct("Did you burn your showroom?", "\"No. It was my livelihood. I'd never destroy it.\""), .direct("What was the device?", "\"I don't know. I never saw a candle and timer. I don't understand it.\""), .direct("What can you tell us about your showroom?", "\"I'd owned it for twelve years, and it was my livelihood and my life's work. I knew every piece of furniture on that floor.\""), .direct("What do you think caused the fire?", "\"The wiring was old and an inspector had mentioned it to me the year before. I'd been worried about it for months.\""), .direct("Why did you raise the coverage?", "\"The agent recommended it after a renovation. I didn't think about the debt.\""), .direct("What did you do after you learned the showroom was on fire?", "\"I drove back and stood across the street. Fire crews were already there, and I told them everyone had left at 7.\""), .cross("You owed $150,000, didn't you?", "\"Yes. Times were hard. That's not why there was a fire.\""), .cross("You filed a $400,000 claim, didn't you?", "\"Yes. It's what the policy covers. I did what any owner would.\""), .cross("You left at 7 p.m., didn't you?", "\"Yes, as usual. The fire came later.\""), .cross("Business at the showroom was slow that year, wasn't it?", "\"It was slower than I wanted, like a lot of showrooms that year, but we were open and I still had customers coming in.\""), .cross("You left at seven and the fire started at eleven. Where were you?", "\"At home with my family. I got the call from the fire department at about midnight and drove straight over.\"")],
        openings: ("A furniture showroom burned, and investigators found a candle-and-timer device. {D}, the owner, owed $150,000 and filed a $400,000 claim, leaving at 7 p.m. The State will present the fire marshal and the finances.", "The defense will present old wiring flagged by an inspector, an owner who lost everything, and no one who saw a device set. Listen closely to the witnesses."),
        closings: ("A candle-and-timer device found at the origin, $150,000 in debt, a $400,000 claim, and an owner who raised coverage a month before. The fire was set, and {D} had the motive.", "Old wiring that an inspector had flagged, an owner who lost {D.his} life's work, and a device nobody can tie to {D}. The State has not proved who set the fire."),
        timeline: [(-30, "Coverage is raised."), (0, "7 p.m.: {DL} leaves."), (0, "11 p.m.: the fire."), (7, "The claim.")],
        identified: "A fire report.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let groupHomeWanderFreezeV1 = SmallCases.make(
        key: "story.groupHomeWanderFreeze",
        category: .family,
        headlines: ["Resident Lost in Ice Storm After Night Aide Left Door Propped", "Found in a Drainage Ditch"],
        law: "patientNeglect",
        threshold: 7,
        spec: "Neglected a disabled adult in {D}'s care, causing serious injury, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V}, a resident with dementia, left a group home on {DATE} during an ice storm after {D}, the night aide, propped the door. {V} was found in a ditch. {DL} says the door stuck.",
        state: [E(.statement, 3, "Supervisor", "The door was shut at shift change."), E(.forensic, 3, "Medical Report", "Hypothermia."), E(.video, 2, "Porch Camera", "{D} props the door.")],
        defense: [E(.statement, 1, "Stuck", "{DL} says the door would not latch.")],
        role: "Group home supervisor",
        exam: [.direct("What can you tell us about your job and the home?", "\"I'm the supervisor of a group home for residents with dementia. We have six residents and one aide on overnight shift.\""), .direct("What happened at the group home on {DATE}?", "\"During an ice storm, {V}, a resident with dementia, left through a door that {D}, the night aide, had propped. {V} was found in a ditch with hypothermia.\""), .direct("Was the door secure earlier?", "\"Yes. It was shut at shift change. The porch camera shows {DL} propping it.\""), .direct("What was {V}'s condition?", "\"Hypothermia, according to the medical report. {V} was lucky to survive.\""), .direct("How were the doors kept secure?", "\"Every exterior door has a latch and an alarm chime. The front door was shut and latched at shift change at 11 p.m.\""), .direct("What happened that night?", "\"During an ice storm, the aide propped the front door open. A porch camera recorded it at about midnight, and {V} walked out at 12:30.\""), .cross("{DL} says the door would not latch, doesn't {D.he}?", "\"We had latch problems. But propping the door open in an ice storm was wrong.\""), .cross("Did {DL} report the latch?", "\"I don't have a report that night. A repair was requested earlier.\""), .cross("Was {DL} the only aide?", "\"Yes. That's our night staffing. It's thin.\""), .cross("Was the latch repaired before that night?", "\"It had been reported twice. Parts were on order and we hadn't had them yet.\""), .cross("Did the aide tell you the door was propped?", "\"No. I learned it from the camera the next morning.\"")],
        defenseRole: "Maintenance worker",
        defenseExam: [.direct("Describe your job and the latch for the jury.", "\"I'm the maintenance worker for the home. I fix doors, heating, and plumbing.\""), .direct("Do you maintain the home?", "\"Yes. I'm the maintenance worker.\""), .direct("Was the latch broken?", "\"Yes. It wouldn't catch. A repair was requested twice.\""), .direct("Did you fix it?", "\"Not yet. Parts were slow.\""), .direct("What was wrong with the latch?", "\"The strike plate was bent and the spring was weak, so the door swung shut but wouldn't always catch, especially in cold weather when the frame contracted.\""), .direct("What had you done about it?", "\"I reported it to the supervisor twice in writing and ordered a replacement latch. The part had not arrived by the night of the ice storm.\""), .cross("Could the door be secured another way?", "\"Yes. A chain or a wedge from inside. {D} could have.\""), .cross("Did you tell {DL} about it?", "\"Yes. Everyone knew. I told {DL}, and so did everyone else.\""), .cross("Is propping it open acceptable?", "\"No. It isn't. Not at night.\""), .cross("Did the door have a lock?", "\"Yes, a simple deadbolt that locks from the outside. There was no inside latch.\""), .cross("Was propping it open ever allowed?", "\"No. It was never allowed, and especially not at night during a storm, and every staff member had been told that in training.\"")],
        theory: ("{D} propped a door.", "A stuck latch."),
        allocution: "\"The latch wouldn't hold, and it kept swinging shut and locking me out. I thought {V} was asleep, and I should have checked. When I realized, I searched and called for help. I'm devastated, and I never meant for {V} to be hurt. I'm sorry for what I put my family through.\"",
        truths: ("{DL} stepped out to smoke.", "The latch repair was requested twice."),
        defendant: [.direct("Why did you prop the door?", "\"The latch wouldn't hold, and it kept swinging shut and locking me out. I propped it briefly.\""), .direct("Did you know {V} might leave?", "\"I didn't think so. {V} was asleep. I should have checked.\""), .direct("What did you do when you realized?", "\"I searched and called for help. I'm devastated. I never meant for {V} to be hurt.\""), .direct("What can you tell us about your night shift?", "\"I was the only aide for six residents. It was an ice storm and the power flickered several times.\""), .direct("Why did you step outside?", "\"I went out to smoke. The door wouldn't catch behind me, so I propped it to avoid locking myself out.\""), .direct("How did you discover {V} was missing?", "\"At about 1:30 I did a room check and found the bed empty. I searched and called the supervisor.\""), .cross("You propped the door open during an ice storm, didn't you?", "\"Yes. It was a bad decision. I didn't think about the storm.\""), .cross("It was your job to keep residents safe, wasn't it?", "\"Yes. I failed. I'm so sorry.\""), .cross("You were the only aide, weren't you?", "\"Yes. That's a lot of responsibility.\""), .cross("You propped the door in an ice storm. Wasn't that dangerous?", "\"Yes. I didn't think anyone would wake. It was a terrible mistake.\""), .cross("You stepped outside for a cigarette during a shift. Was that allowed?", "\"No. I shouldn't have left the floor. I'm deeply sorry.\"")],
        openings: ("During an ice storm, {D}, the night aide, propped a door at a group home, and {V}, a resident with dementia, wandered out and was found in a ditch with hypothermia. The porch camera shows the prop. The State will present the supervisor and the medical report.", "Jurors will also see a latch that would not hold, repairs requested twice, and an aide alone at night who made a bad choice. Listen closely to the witnesses."),
        closings: ("A door propped open in an ice storm, a resident with dementia found in a ditch with hypothermia, and an aide who stepped outside to smoke. {D} was the one responsible for keeping {V} safe.", "A latch that would not hold, repairs requested twice, and one aide alone with six residents. The State must prove {D} willfully neglected {V}, and a bad decision on a bad night is not that."),
        timeline: [(0, "Midnight: the door."), (0, "12:30 a.m.: {V} leaves."), (0, "5 a.m.: found."), (1, "{DL} is suspended.")],
        identified: "A porch camera.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .divided,
        impact: "My parent was never the same. {V} came back from the hospital confused and frightened, and the doctors said the cold did permanent harm. Before that night my parent knew all our names. Now there are days when I'm a stranger. We trusted that home with our whole lives.",
        doctrines: ["burdenOfProof"],
        genders: ["V": .female])

    static let roofingWidowScamV1 = SmallCases.make(
        key: "story.roofingWidowScam",
        category: .whiteCollar,
        headlines: ["Driveway Paving Crew Charged Widower for Work Never Needed", "Old Asphalt Re-Sprayed With Oil"],
        law: "exploitationElder",
        threshold: 8,
        spec: "Exploited an elder adult by deception, obtaining $18,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A widower, {V}, paid $18,000 to {D}'s crew on {DATE} for a driveway replacement that was only oil sprayed on old asphalt. {DL} says the work was a premium seal.",
        state: [E(.document, 3, "Inspector Report", "Old asphalt; no new layer."), E(.document, 3, "Contract", "$18,000 signed on the spot."), E(.digital, 2, "Photos", "Photos from another job.")],
        defense: [E(.statement, 1, "Seal", "{DL} says the work was a premium seal.")],
        role: "Home inspector",
        exam: [.direct("Tell the jury how you came to hire {D}'s crew.", "\"A crew knocked on my door and said they were finishing a job nearby and could replace my driveway at a discount. I'm a widower and I trusted them.\""), .direct("What did you pay the defendant's crew to do for you?", "\"A driveway replacement for $18,000. It turned out to be oil sprayed over my old asphalt, with nothing new laid down.\""), .direct("What did the home inspector find when looking at the work?", "\"Old asphalt with no new layer on top. The contract had been signed on the spot, the same day the crew arrived.\""), .direct("What about the photos that you were shown by the crew?", "\"They were photos from another job, not my driveway. I did not know that until the inspector told me.\""), .direct("What happened when you signed?", "\"They had a contract ready and said the price would go up if I waited. I signed that day and paid $18,000.\""), .direct("What did the work look like?", "\"A crew sprayed a black coating on my old driveway and left within a few hours. It looked shiny, but every crack and pothole was still there underneath.\""), .cross("{D} says the work was a premium seal, doesn't {D.he}?", "\"Seal work is common, and a paving supplier says {D} bought sealant, not asphalt. I will say that fits that story.\""), .cross("Did you sign the contract the very same day it was offered?", "\"Yes. {D.He} pressured me to sign that day, and I did. I should have waited and compared prices.\""), .cross("Did you ask other contractors for bids on a driveway?", "\"No. I did not. I wish I had, because I would have learned the price was far too high.\""), .cross("Did you ask for time to think?", "\"I did. They said the price would go up and the crew would leave.\""), .cross("Did you compare quotes?", "\"No. I should have, and I regret that.\"")],
        defenseRole: "Paving supplier",
        defenseExam: [.direct("Tell us about your supply yard.", "\"I run a paving supply yard. Contractors buy asphalt, sealant, and equipment from me.\""), .direct("What did {D} buy from your paving supply yard that week?", "\"Sealant. {D} bought a large amount of sealant, enough for several driveways, and paid for it in full.\""), .direct("Did the defendant buy any asphalt from you for that job?", "\"No. Not asphalt. I did not sell {DF} any asphalt that week, or in the weeks before that.\""), .direct("Is sealant a common product for contractors to buy?", "\"Yes. Many contractors apply sealant to driveways. It is a normal job and a normal product to sell.\""), .direct("How much sealant does a normal driveway need?", "\"A typical driveway takes a handful of five-gallon buckets, and what {DF} bought was far more than that.\""), .direct("How is sealant sold at your yard?", "\"By the five-gallon bucket, and contractors usually buy it by the pallet for bigger jobs.\""), .cross("Would a sealing job cost anywhere near $18,000 for a driveway?", "\"No. A sealing job costs far less than that. I would call that price very high for the work.\""), .cross("Would sealant replace the asphalt in a driveway that is worn?", "\"No. It would not. It is only a surface treatment, and it does not give a new driveway.\""), .cross("Did the defendant tell you what the sealant was going to be used for?", "\"No. I did not ask, and {D.he} did not say. It is not something I normally ask a customer.\""), .cross("You sold the sealant at your regular contractor price, didn't you?", "\"Yes, it was the regular contractor price, and there was nothing unusual about the sale.\""), .cross("Did the defendant buy anything for a replacement?", "\"No. {D.He} bought only sealant that week.\"")],
        theory: ("{D} sold fake paving.", "A premium seal."),
        allocution: "\"I applied a premium seal, and that's what I thought I sold. It was a large driveway and I used a lot of product. My crew was in the area, and I wanted to lock in the work. I knew better than to bill it as a replacement.\"",
        truths: ("{DL} pressured {V} to sign the same day.", "Seal work is common."),
        defendant: [.direct("Did you replace the driveway?", "\"No. I applied a premium seal. That is what I thought I sold.\""), .direct("Why did you ask for $18,000?", "\"It was a large driveway, and I used a lot of product. I believed the price was fair.\""), .direct("Why did you ask {V} to sign that day?", "\"My crew was in the area. I wanted to lock in the work.\""), .direct("Please describe your business.", "\"I run a small paving and sealing crew. We do driveways, parking lots, and seal coating.\""), .direct("What did you sell {V}?", "\"A premium seal that protects the driveway and extends its life. I wrote the contract as a replacement because that's the word I use.\""), .direct("Did {V} ask for time to think?", "\"Yes. {V.He} asked to read it over first, and I said the price would change if we waited.\""), .cross("Photos from another job were shown to {V}, weren't they?", "\"I used photos of a similar job. It was not honest.\""), .cross("$18,000 for oil on old asphalt. Will you refund it?", "\"Yes. I will. I am sorry.\""), .cross("The contract said replacement. Isn't that false?", "\"I wrote it that way. I didn't explain well, and I regret that.\""), .cross("$18,000 for oil sprayed on old asphalt. Isn't that a rip-off?", "\"It's a premium product, and the driveway was large. I thought the price was fair.\""), .cross("The photos you showed {V} were from other jobs, weren't they?", "\"Yes. I used them to show the kind of work we do, and I should have said they were not {V}'s driveway.\"")],
        openings: ("{V}, a widower, paid $18,000 to {D}'s crew for a driveway replacement and received only oil sprayed on old asphalt. The inspector found no new layer, and {V} was shown photos from another job.", "The defense case is that {D} bought sealant for premium seal work, which is common, and that {D.he} never meant to cheat."),
        closings: ("A contract for replacement, $18,000 paid on the spot, photos from another job, and old asphalt under a coat of oil. {V} was sold work that was never done.", "A premium seal and a contractor who did what the supplier records show. The State must prove {D} meant to deceive, and a poor contract is not a crime."),
        timeline: [(0, "The knock."), (0, "Noon: the contract."), (7, "The work."), (60, "The inspection.")],
        identified: "An inspector.",
        aggravating: ["The victim was particularly vulnerable", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I thought those men were kind. They came to my door saying they had leftover asphalt, and I'd just lost my wife. I paid eighteen thousand dollars for a new driveway. It washed away in the first rain. I feel foolish, but I was alone.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let loanSharkThreatsV1 = SmallCases.make(
        key: "story.loanSharkThreats",
        category: .whiteCollar,
        headlines: ["Lender Threatened Borrower's Family on Porch", "Doorbell Camera Records the Visit"],
        law: "extortion",
        threshold: 7,
        spec: "Threatened {V} with injury to obtain payment of $8,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} loaned {V} $3,000 and demanded $8,000, appearing on {V}'s porch on {DATE} and saying 'family pays.' {DL} says it was collection talk.",
        state: [E(.video, 3, "Doorbell Camera", "{D} on the porch."), E(.document, 2, "Loan Note", "$3,000 at 300%."), E(.statement, 2, "Spouse", "'We hid the kids.'")],
        defense: [E(.statement, 1, "Collection", "{DL} says it was collection talk.")],
        role: "Detective",
        exam: [.direct("Walk us through how you came to investigate.", "\"{V} called the sheriff's office after a visit from {D}. The doorbell camera recorded {DL} on the porch at about seven.\""), .direct("What happened at {V}'s porch on that date?", "\"{DL} loaned {V} $3,000 and demanded $8,000. {DL} appeared on {V}'s porch and said 'family pays.'\""), .direct("What does the doorbell camera show of the visit?", "\"{DL} on the porch. It shows the visit and, with the audio, the words that {DL} used to {V}.\""), .direct("What did {V}'s spouse tell you after the visit?", "\"'We hid the kids.' The family was afraid for the children after {DL} said what {DL} said.\""), .direct("What was the loan arrangement?", "\"{V} borrowed $3,000 from {DL} and signed a note at 300 percent interest. {DL} then demanded $8,000.\""), .direct("What did {D} say to {V} when {D} stood on the porch?", "\"{DL} said 'family pays' and told {V} the debt would be collected one way or another. It sounded like a threat, and {V} locked the door.\""), .cross("{D} says it was only collection talk, doesn't {D.he}?", "\"Yes. {DL} came back the next day, too, and I will say that {DL} did not shout or touch anyone.\""), .cross("Did {V} sign the loan note freely at the beginning?", "\"Yes. {V} signed it. It carries interest at 300 percent, which is far above any legal rate.\""), .cross("Did {D} raise {D.his} voice on the porch during the visit?", "\"No. {D.He} did not shout. {D.He} spoke in an ordinary voice, as far as the recording shows.\""), .cross("Did the defendant raise {D.his} voice?", "\"The video shows a conversation, and I can't make out every word.\""), .cross("Did the defendant touch anyone?", "\"No. {D.He} stayed on the porch.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Explain to the jury how you know the neighbors.", "\"I live two houses down. I heard some of the conversation on the porch.\""), .direct("Did {D} shout while standing on the porch of {V}'s home?", "\"No. {D} did not shout at all. {D.He} spoke in a regular voice, and I could hear it from two houses down.\""), .direct("Did you hear any of the words that the defendant said on the porch?", "\"Some. I heard 'family pays,' but I did not catch the rest of what was said during the visit.\""), .direct("Did the defendant come back to the porch on the following day?", "\"Yes. The next day {DF} knocked again. {DF} stood on the porch for a few minutes and then left.\""), .direct("How far were you from the two of them?", "\"About twenty feet, across the lot, with a clear view of both.\""), .direct("How did the defendant behave?", "\"Calm. {D.He} spoke in a regular voice and didn't threaten.\""), .cross("How far were you from {V}'s porch when you heard that?", "\"Two houses down. I could hear some of it, but not all, since the wind carried some of the words away.\""), .cross("What did you take the words 'family pays' to mean at the time?", "\"I thought it meant that the family would be responsible for the debt. It sounded like a warning to me.\""), .cross("Did {V} seem afraid to you when the defendant came to the door?", "\"Yes. {V} looked scared. I saw {V} pull the curtains shut and bring the children inside.\""), .cross("Could you hear everything?", "\"No. I was two houses away.\""), .cross("Did you see the children hide?", "\"No. I only know what I heard.\"")],
        theory: ("{D} threatened a family.", "Collection."),
        allocution: "\"I said family pays as collection talk, meaning the household would owe the debt. I went in person because I was owed money. {V} signed freely, and I did not force anyone. I overstepped, and I'm sorry to {V} and the family.\"",
        truths: ("{DL} came back the next day.", "{V} signed the note."),
        defendant: [.direct("Did you threaten {V}'s family on the porch?", "\"No. I said 'family pays' as collection talk. I meant the household would be responsible for the debt that was owed.\""), .direct("Why did you go to {V}'s porch that day?", "\"To collect. I was owed money, and I went to talk about it in person, since calls were not working.\""), .direct("Did {V} sign the loan note when the loan was made?", "\"Yes. {V} signed it freely. I did not force anyone, and I explained the terms before the signing.\""), .direct("What can you tell us about your lending business?", "\"I lend small amounts to people who can't get bank loans. I charge a high rate, and borrowers know the terms.\""), .direct("What did you say on the porch?", "\"That the debt had to be paid and that family pays. I meant that families help each other pay.\""), .direct("Why did you come back the next day?", "\"To talk again. I hoped {V} would agree to a plan.\""), .cross("You came back to the porch the next day, didn't you?", "\"Yes. I wanted to talk again, and I still had not been paid anything toward the debt.\""), .cross("300 percent interest on a $3,000 loan. Isn't that predatory?", "\"It is high. I know that. {V} agreed to it, and I did not hide the number from {V.him}.\""), .cross("'Family pays.' How is that not a threat to {V}'s children?", "\"I see how it sounds now. I did not mean any harm to anyone's children, and I am sorry it sounded that way.\""), .cross("{V} stopped answering your calls before you went to the porch, didn't {V.he}?", "\"Yes, the calls went unanswered, which is why I went in person. I should have tried another way.\""), .cross("The family hid their children. Doesn't that tell you something?", "\"It tells me they were afraid. I didn't mean to frighten anyone.\"")],
        openings: ("{D} loaned {V} $3,000 and demanded $8,000, appearing on {V}'s porch and saying 'family pays.' The doorbell camera recorded it, and {V}'s family hid the children.", "Weigh the defense proof, which will show that {V} signed the note, that {D} was loud only in words, and that 'family pays' was collection talk."),
        closings: ("A loan at 300 percent, a visit to the porch, and the words 'family pays.' {V}'s family hid the children in fear.", "A signed loan and a collection visit. The State must prove {D} threatened {V}'s family, and a collection phrase is not a threat."),
        timeline: [(-30, "The loan."), (0, "7 p.m.: the porch."), (1, "The return visit."), (2, "{V} reports.")],
        identified: "A doorbell camera.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "We moved. After that man showed up on our porch and said family pays, we couldn't stay. I put my children in a new school and left a house I loved. I borrowed three thousand and was told I owed eight. I keep looking at the porch light.",
        doctrines: ["burdenOfProof"])

    static let bailBondsJailerV1 = SmallCases.make(
        key: "story.bailBondsJailer",
        category: .whiteCollar,
        headlines: ["Bondsman Paid Court Clerk for Early Warrant Lists", "Cash App Trail Shows Weekly Payments"],
        law: "bribery",
        threshold: 7,
        spec: "Corruptly gave a thing of value to a public official, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D}, a bail bondsman, paid a court clerk $250 a week for early warrant lists on {DATE}. App records show payments. {DL} says it was babysitting pay.",
        state: [E(.digital, 3, "Payment App", "Weekly $250 to the clerk."), E(.digital, 3, "Texts", "'Anything new?'"), E(.statement, 2, "Clerk", "'I sent lists.'")],
        defense: [E(.statement, 1, "Babysitting", "{DL} says it was babysitting pay.")],
        role: "Court administrator",
        exam: [.direct("Please tell us about your role at the court.", "\"I'm the court administrator. I oversee the clerk's office, including how warrant lists are handled and who is allowed to see them before they go out.\""), .direct("What did your review find about {DL}'s payments?", "\"{D}, a bail bondsman, paid a court clerk $250 a week for early warrant lists. App records show the payments.\""), .direct("What did the clerk say?", "\"'I sent lists.' The clerk admitted sending them.\""), .direct("What did the audit find?", "\"Payments of $250 a week from {DL}'s account to a court clerk. The payments began three months before the audit.\""), .direct("When did the clerk send the lists?", "\"In the weeks before the incident. The texts are dated, and the clerk confirmed the dates.\""), .direct("What did you do with the clerk's phone records during the audit?", "\"We matched each weekly payment to a list sent within hours. The lists went out before the warrants were public.\""), .cross("{DL} says it was babysitting pay, doesn't {D.he}?", "\"The clerk says lists were sent. The texts ask for news.\""), .cross("Does {DL} have children?", "\"I believe so. I haven't confirmed.\""), .cross("Is early warrant information sensitive?", "\"Yes. It lets a bondsman approach people first. That's the problem.\""), .cross("Is it a crime to pay a clerk for babysitting?", "\"No. If the payments were for childcare, that would be lawful.\""), .cross("Did you see the clerk send lists?", "\"I saw messages that say so. I didn't see the lists.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Walk us through how you know {D}.", "\"I live across the street from {D}. I've seen the clerk come and go from {DF}'s house on many evenings over the past year.\""), .direct("Do you live near {DL}?", "\"Yes. Across the street. I live across the street from {DL}.\""), .direct("How often?", "\"A few times a week. I'm not sure exactly.\""), .direct("Did the clerk watch the defendant's children?", "\"Yes. A few times a week, usually in the evening, as far as I could tell from watching from my front window.\""), .direct("Did you see anything unusual?", "\"No. The clerk arrived and left with the children each time, and I never saw anything exchanged at the door.\""), .direct("What time of day did the clerk usually come to the house?", "\"Usually early in the evening, around the time people get home from work, and the clerk typically left before it got late.\""), .cross("Did you know the clerk worked at the court?", "\"Yes. That was common knowledge.\""), .cross("Did you see warrant lists?", "\"No. I know nothing about that.\""), .cross("Did you see payments?", "\"No. I never saw money change hands, and I never saw any paperwork or lists being carried in or out of the house.\""), .cross("You never went inside the defendant's house, did you?", "\"No. I only watched from my front window across the street, so I cannot say what went on inside.\""), .cross("You did not see the money change hands, did you?", "\"No. I was only there for the pickups. I do not know when or how {DF} paid the clerk.\"")],
        theory: ("{D} paid for lists.", "Babysitting."),
        allocution: "\"The clerk watched my children, and I paid weekly for babysitting. We talked about how the kids were. It was casual and not about warrants. The clerk sent me things sometimes, and I didn't ask for them. I'm ashamed of how it looks, and I'm sorry.\"",
        truths: ("Lists were sent before warrants issued.", "{DL} paid for childcare earlier."),
        defendant: [.direct("Why did you pay the clerk?", "\"For babysitting. The clerk watched my children, and I paid weekly. It was a friendship.\""), .direct("What did 'anything new?' mean?", "\"How the kids were. It was casual. It wasn't about warrants.\""), .direct("Did you get warrant lists?", "\"No. The clerk sent me things sometimes. I didn't ask for them.\""), .direct("Tell the jury about your family.", "\"I have two young children. The clerk watched them a few evenings a week, and I paid $250 weekly.\""), .direct("What did you pay the clerk for, in your own words?", "\"I paid for help with childcare when my schedule changed. I never asked about warrant lists, and I do not think of this as buying information.\""), .direct("How did you find out the clerk had been sending lists?", "\"The clerk told me afterward, when the investigators arrived. I had not known the lists were leaving the office.\""), .cross("You paid $250 a week, didn't you?", "\"Yes. I paid well for childcare. It was a lot, but worth it.\""), .cross("The clerk says lists were sent, doesn't the clerk?", "\"I don't recall that. It may have happened without my asking.\""), .cross("You work as a bail bondsman, don't you?", "\"Yes. I deal with the court. That doesn't make this a bribe.\""), .cross("You're a bail bondsman. Isn't an early warrant list valuable?", "\"It would be. I never wanted one.\""), .cross("You kept paying every week for months, didn't you?", "\"Yes. It became routine. I should have asked what the money was really for.\"")],
        openings: ("{D}, a bail bondsman, paid a court clerk $250 a week for early warrant lists. App records show weekly payments, texts ask 'Anything new?', and the clerk says lists were sent. The State will show the payments and the clerk.", "The defense will present a babysitting arrangement, a neighbor who saw the clerk with {D}'s children, and payments that fit childcare. Listen closely to the witnesses."),
        closings: ("Weekly payments of $250, texts asking for news, and a clerk who says lists were sent. Payments for early warrant information are exactly what the law forbids.", "Payments for babysitting are not bribes. A neighbor saw the clerk with {D}'s children, and the State has not proved the money was for warrant lists."),
        timeline: [(-90, "Payments begin."), (0, "Month 3: audit."), (0, "Month 3: texts found."), (1, "{DL} is charged.")],
        identified: "A payment app.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let barnFeudFireV1 = SmallCases.make(
        key: "story.barnFeudFire",
        category: .violent,
        headlines: ["Hay Barn Burned After Fence Dispute; Neighbor's Tractor Seen", "Burn Pattern Follows a Trail of Straw"],
        law: "burningBuildings",
        threshold: 8,
        spec: "Willfully and maliciously burned a barn owned by {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A hay barn burned overnight on {DATE} after a fence dispute. A trail of straw led from the road. {D}'s tractor was seen. {DL} says {D.he} was checking a fence.",
        state: [E(.forensic, 3, "Fire Report", "A straw trail with accelerant."), E(.video, 2, "Road Camera", "{D}'s tractor at midnight."), E(.statement, 2, "Neighbor", "Saw a light.")],
        defense: [E(.statement, 1, "Fence", "{DL} says {D.he} was checking a fence.")],
        role: "Fire marshal",
        exam: [.direct("What can you tell us about the barn and the fire?", "\"A hay barn burned overnight. When we arrived, the barn was fully involved, and we found a trail of straw leading from the road.\""), .direct("How many firefighters responded?", "\"Two engines and about eight firefighters. They kept it from reaching the house.\""), .direct("What does the road camera show?", "\"{D}'s tractor at midnight. A neighbor also saw a light.\""), .direct("What does the fence dispute have to do with it?", "\"{DL} and the barn's owner argued over a fence. That's the background.\""), .direct("What did the lab find?", "\"Accelerant on the straw trail. It was gasoline, spread along the path.\""), .direct("How did {D} come into the case?", "\"A road camera shows {DL}'s tractor passing at midnight, and a neighbor saw a light near the barn later.\""), .cross("{DL} says {D.he} was checking a fence, doesn't {D.he}?", "\"Fences do need checking. But a straw trail with accelerant is not fence work.\""), .cross("Did anyone see {DL} set the fire?", "\"No. No one saw that. I have the tractor on camera.\""), .cross("Is the tractor unique?", "\"No. Many tractors look alike. It's {D.his} by registration.\""), .cross("Could a tractor have been passing for another reason?", "\"Yes. It's a farm road.\""), .cross("The straw trail started at the road and ended at the barn, didn't it?", "\"Yes. That is why we think someone came by vehicle and laid it on foot. The accelerant matched a gas can found nearby.\"")],
        defenseRole: "Veterinarian",
        defenseExam: [.direct("Tell the jury about your practice.", "\"I'm a large-animal veterinarian. I treat cattle on farms throughout the area and I'm on those roads at all hours.\""), .direct("Do you treat cattle in the area?", "\"Yes. I'm a veterinarian. I know the farms.\""), .direct("Do fences get broken?", "\"Often. Cattle push on them. Farmers check them at odd hours.\""), .direct("Do you know {DL}'s cattle?", "\"Yes. {D} has a herd near the line.\""), .direct("Do fences break often?", "\"Yes. Cattle push on fences constantly, especially after a storm or when the grass on the other side looks better.\""), .direct("Would a farmer check a fence at night?", "\"If cattle are out, yes. A farmer would take a tractor and a flashlight and check the fence line right away, even at midnight.\""), .cross("Did you see the fire?", "\"No. I heard about it afterward.\""), .cross("Would a farmer take a tractor at midnight?", "\"Sometimes. If cattle are out. I can't say about that night.\""), .cross("Did you see {D} that night?", "\"No. I wasn't there that night, and I can't tell the jury where {D.he} was or what {D.he} did.\""), .cross("Can you say the defendant was checking the fence?", "\"No. I only know that checking a fence at night is plausible, because I've seen farmers do exactly that many times.\""), .cross("You were not at the farm that night, were you?", "\"No. I know cattle and fences and how often they break. I cannot tell you where {D.he} was or what {D.he} did at midnight.\"")],
        theory: ("{D} burned a barn.", "A fence check."),
        allocution: "\"I was checking a fence because cattle had been getting through, and I went home. I'd never burn a barn. It's a long-standing argument over that line, and I should have walked away from it long ago. I'm sorry for my neighbor's loss.\"",
        truths: ("{DL} had threatened {V} at the fence.", "A cow had broken through at 11."),
        defendant: [.direct("Why was your tractor on the road at midnight?", "\"I was checking a fence. Cattle had been getting through, and I wanted to make sure it was secure.\""), .direct("Did you burn the barn?", "\"No. I'd never burn a barn. I checked the fence and went home.\""), .direct("What about the fence dispute?", "\"It's a long-standing argument. I'd never destroy property over it.\""), .direct("Describe the fence dispute in your own words.", "\"{V} and I have argued about a boundary fence for years. It's a long-standing disagreement.\""), .direct("How long have you kept cattle along that fence?", "\"Over twenty years. I know how cattle push on a fence line, and a break at night is nothing unusual.\""), .direct("Did you see the barn that night?", "\"I passed it on the way along the road. I didn't stop and I didn't see any fire or any light near the barn.\""), .cross("Your tractor passed the barn at midnight, didn't it?", "\"Yes. It's on my route. I didn't stop.\""), .cross("A straw trail led from the road, didn't it?", "\"That's what they say. I didn't see it.\""), .cross("You and the owner disputed a fence, didn't you?", "\"Yes. It's been going on a while.\""), .cross("You threatened {V} at the fence. Isn't that a motive?", "\"I said some sharp words at the fence once. I'd never destroy someone's property over a boundary line, no matter how angry I was.\""), .cross("You and {V} have not spoken in a friendly way since the argument at the fence, have you?", "\"We have not had a friendly word in a long time, but that is a long way from setting someone's barn on fire.\"")],
        openings: ("A hay barn burned overnight after a fence dispute, with a straw trail and accelerant leading from the road. {D}'s tractor was on the road camera at midnight. The State will show the report and the camera.", "Jurors will also see a farmer checking a fence at night, a veterinarian who knows fences break, and no one who saw {D} set a fire."),
        closings: ("A fence feud, a straw trail with accelerant, and {D}'s tractor at midnight. The motive and the opportunity point to one person, and a barn is ashes.", "A tractor passing on a farm road at night and a cow that broke through a fence. The State has not proved {D} set the fire."),
        timeline: [(-14, "The fence dispute."), (0, "Midnight: the tractor."), (0, "1 a.m.: the fire."), (0, "2 a.m.: crews.")],
        identified: "A camera.",
        mood: .divided,
        impact: "Three generations of work went up in that fire. My grandfather built that barn, and my father filled it with hay every summer. I saw the straw trail from the road, and I knew it wasn't an accident. We lost hay, tools and sixty years of our family's history.",
        doctrines: ["burdenOfProof"])

    static let chaserStagedInjuriesV1 = SmallCases.make(
        key: "story.chaserStagedInjuries",
        category: .whiteCollar,
        headlines: ["Medical Billing Rep Recruited Patients for Staged Slip-and-Fall Claims", "Same Store, Same Wording"],
        law: "insuranceFraud",
        threshold: 8,
        spec: "Presented false insurance claims totaling $70,000, on or about {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D}, a billing rep, recruited people to file slip-and-fall claims at one store on {DATE}. Claims used the same words. {DL} says {D.he} only referred patients.",
        state: [E(.document, 3, "Claim Files", "Eleven claims at one store."), E(.digital, 3, "Texts", "'$400 if you say you fell.'"), E(.document, 2, "Payment Ledger", "Payments to claimants.")],
        defense: [E(.statement, 1, "Referral", "{DL} says {D.he} only referred patients.")],
        role: "Insurance investigator",
        exam: [.direct("Please tell us about your job and how this case came to you.", "\"I'm an insurance investigator. A store's insurer noticed eleven slip-and-fall claims at one location in five months, and asked me to look at the pattern.\""), .direct("What did your investigation find?", "\"Eleven slip-and-fall claims at one store using the same words. {D}, a billing rep, recruited the claimants.\""), .direct("What do the texts say?", "\"'$400 if you say you fell.' That's from {D.his} phone.\""), .direct("What does the payment ledger show?", "\"Payments to claimants. It shows money going to the people who filed claims.\""), .direct("What was unusual about the claims?", "\"The statements used nearly identical words, the injuries were similar, and the claimants all came through the same clinic and the same billing representative.\""), .direct("How did you link {D} to the claimants?", "\"Text messages showed {DL} offering claimants money to say they fell, and a ledger showed payments from {DL}'s account to several of them.\""), .cross("{DL} says {D.he} only referred patients, doesn't {D.he}?", "\"Referrals are legal. But the texts offer money for a claim.\""), .cross("Did some patients really fall?", "\"Some may have. I can't say none did.\""), .cross("Did {DL} file any claim?", "\"No. {D.He} recruited. Others filed.\""), .cross("Were any of the falls real?", "\"Some may have been. I can't tell the jury none of them happened, only that the pattern suggested staging.\""), .cross("Did the defendant write the claims?", "\"No. The claims were written by the claimants and filed through attorneys. I can't say {DL} wrote any of them.\"")],
        defenseRole: "Clinic nurse",
        defenseExam: [.direct("Tell us about your work at the clinic.", "\"I'm a nurse. I see patients every day, take histories, document injuries, and assist the doctors with exams.\""), .direct("Were injuries real?", "\"Some were. I documented injuries on several patients.\""), .direct("Did {DL} refer patients?", "\"Yes. {D} sent them our way.\""), .direct("What did the fractured wrist look like on the scan?", "\"A clean break consistent with a fall on a hard floor, not with a twisting injury.\""), .direct("Did the defendant ever tell you what to write in a chart?", "\"No. {D.He} never told me what to write in any chart, and I would have refused and told the doctor if {D.he} had ever tried.\""), .direct("How were patients from the defendant different from others?", "\"They arrived together and had similar complaints. I noted that, and I did not question it because the exams showed some real strain.\""), .cross("Were all injuries real?", "\"No. Some were harder to verify.\""), .cross("Did you see the texts?", "\"No. I only heard about them.\""), .cross("Did {DL} tell you what to write?", "\"No. Never. {DL} never told me what to write.\""), .cross("Were all the injuries easy to verify?", "\"No. A few were harder to confirm, like back pain without visible bruising, and I recorded what the patient said.\""), .cross("Did you see the text offering $400?", "\"No. I never saw that text. I only heard about it afterward from the investigator, and I found it troubling when I did.\"")],
        theory: ("{D} staged falls.", "A referrer."),
        allocution: "\"I was a billing rep at a clinic, and I referred patients who told me they'd been hurt. I never staged anything, and I only talked to patients. I did billing and referrals. I knew better than to repeat the same story to everyone.\"",
        truths: ("{DL} was paid per patient.", "Some patients truly fell."),
        defendant: [.direct("What was your job?", "\"I was a billing rep at a clinic. I referred patients who said they were hurt.\""), .direct("Did you stage falls?", "\"No. I never staged anything. I only talked to patients.\""), .direct("Tell us what you did at the clinic.", "\"I did billing and referrals. I scheduled patients, submitted insurance paperwork, and sent patients to the store's claims office when they had been hurt.\""), .direct("What did the text about $400 mean?", "\"It was a bad way to say it. I meant that people who truly fell could get help with their bills, and I phrased it carelessly.\""), .direct("Did you pay any claimants?", "\"I gave a few of them small amounts for transportation and lost wages. I didn't think it was wrong, and I never paid anyone to lie.\""), .direct("How did you explain the work to patients when they asked about the claims?", "\"I told them the clinic could help document injuries and that the store's insurer should cover them. I did not tell anyone what to say.\""), .cross("You offered $400 if people said they fell, didn't you?", "\"The text says that. I was careless.\""), .cross("Eleven claims used the same words, didn't they?", "\"I didn't write them. I only referred.\""), .cross("You paid claimants, didn't you?", "\"Some money moved. I thought it was for their time.\""), .cross("You were paid for each patient you referred. Isn't that a motive to push claims?", "\"It's how the clinic pays billing staff. I didn't push claims that weren't real.\""), .cross("Eleven claims at one store in five months. How is that a coincidence?", "\"It's a busy store with a wet floor, and several of my patients shopped there. I never staged anything.\"")],
        openings: ("{D}, a billing rep, recruited claimants for eleven slip-and-fall claims at one store using the same words, and a text offered '$400 if you say you fell.' The State will present the investigator and the payments.", "The defense evidence includes a referral business, a nurse who found real injuries, and a billing rep who never filed a claim. Listen closely to the witnesses."),
        closings: ("Eleven claims at one store, nearly identical words, a text offering $400 if people said they fell, and payments to claimants. {D} recruited the claimants.", "Some of the patients truly fell, and {D} only referred them. The State has not proved {DL} knew any claim was false or that {D.he} staged a single fall."),
        timeline: [(-120, "Claims begin."), (0, "Month 4: pattern."), (0, "Month 5: texts."), (1, "{DL} is charged.")],
        identified: "Claim files.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let hayrideTractorWreckV1 = SmallCases.make(
        key: "story.hayrideTractorWreck",
        category: .traffic,
        headlines: ["Boy Scout Troop Wagon Tips on Hillside, Driver Over the Limit", "Trailer Hitch Pin Missing"],
        law: "felonyDBV",
        threshold: 7,
        spec: "Unintentionally caused the death of {V} while driving impaired, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A trailer carrying a troop tipped on a hillside on {DATE}, killing {V}, a twelve-year-old. {D}, driving the tractor, blew .12. {DL} says a hitch pin failed.",
        state: [E(.forensic, 3, "Breath Result", "A result of .12."), E(.statement, 3, "Leader", "'He took the slope too fast.'"), E(.forensic, 2, "Autopsy", "Fatal head injury.")],
        defense: [E(.document, 1, "Mechanic Note", "A note on a worn hitch pin.")],
        role: "Highway Patrol trooper",
        exam: [.direct("Walk us through what you found at the hillside.", "\"A farm trailer had tipped on a steep slope with about twenty children and adults aboard. {V}, a twelve-year-old, was pinned and died at the scene.\""), .direct("How many children were on the trailer?", "\"Eleven plus {V}. They were sitting on hay bales along both sides.\""), .direct("What did {DL}'s breath test show?", "\"A .12. That's above the legal limit.\""), .direct("What did the troop leader say?", "\"That {D.he} took the slope too fast. The autopsy found a fatal head injury.\""), .direct("What did the troop leader tell you?", "\"That {D.he} took the slope faster than the leader was comfortable with. The leader said several children shouted for {D.him} to slow down.\""), .direct("How was {D} tested?", "\"A breath test at the scene about forty minutes after the tip read .12. That's one and a half times the legal limit for driving.\""), .cross("{DL} says a hitch pin failed, doesn't {D.he}?", "\"A mechanic noted a worn pin. A worn pin and speed can both matter.\""), .cross("Can you say the pin failed?", "\"The trailer tipped, and I can't say which factor caused it.\""), .cross("Was the slope steep?", "\"Yes. It was a hillside. A driver must go slowly there.\""), .cross("Who last inspected the hitch?", "\"The mechanic, a month earlier. His note says the pin was worn and needed replacing.\""), .cross("Was the slope steeper than the trailer's rating?", "\"I don't have a rating for the slope. It was steep enough to require a slow descent.\"")],
        defenseRole: "Farm mechanic",
        defenseExam: [.direct("Tell the jury about your work on {D}'s equipment.", "\"I'm the farm mechanic. I service the tractors and trailers, and I inspected this hitch a month before the ride.\""), .direct("How is a hitch pin supposed to be checked?", "\"You pull it and look for wear, grooves, or bent places, and compare it to a new one. A pin worn to half its thickness is past its service life.\""), .direct("Was the hitch pin worn?", "\"Yes. I noted it. I told {D} it should be replaced.\""), .direct("What did you find on the hitch?", "\"The pin was worn to about half its thickness. I wrote a note and told {DF} it needed to be replaced.\""), .direct("Can a worn pin fail?", "\"Yes. A worn pin can shear under load, especially on a downhill where the trailer pushes forward.\""), .direct("What did you tell the defendant about the pin when you serviced the hitch?", "\"I said it was worn and should be replaced before the next ride. I wrote it on the work order and handed {DF} a copy.\""), .cross("Did you inspect it after the crash?", "\"I looked at it. I can't say it failed.\""), .cross("Was the pin the reason for the tip?", "\"I can't say. A pin can wear without failing.\""), .cross("Did you tell {DL} in writing?", "\"Yes. I left a note.\""), .cross("Did you look at the pin after the crash?", "\"I saw the pin in the wreckage. I can't say whether it failed first or broke in the tip.\""), .cross("Where is the note now?", "\"In my files. I kept a photo of it and the date I left it.\"")],
        theory: ("{D} drove drunk and killed a child.", "A hitch failure."),
        allocution: "\"The trailer started to tip, and I felt the hitch give, and I tried to correct it. I'd had a drink earlier and didn't think I was impaired. I've replayed it every night. A child died. I'll carry this forever, and I'm sorry to {V}'s family and the troop.\"",
        truths: ("{DL} had been drinking at the farm.", "A mechanic flagged the pin the month before."),
        defendant: [.direct("What happened on the slope?", "\"The trailer started to tip, and I felt the hitch give. I tried to correct and couldn't.\""), .direct("Had you been drinking?", "\"I'd had a drink earlier. I felt fine to drive then. I've replayed it every day.\""), .direct("How do you feel about {V}?", "\"Devastated. A child died. I'm devastated about {V}.\""), .direct("Tell the jury how the ride began.", "\"We were giving the troop a hayride around the farm at the end of a camp day. I'd driven it many times before.\""), .direct("What did you do right after the trailer tipped?", "\"I shut the tractor off and ran back to the trailer. The leaders and I pulled children out, and someone called 911 while I stayed with {V}.\""), .direct("What had you had to drink?", "\"One drink earlier at the farm, around lunch. I didn't think it affected me, and I would never have driven if I had.\""), .cross("You blew a .12, didn't you?", "\"Yes. I'm not going to argue the number.\""), .cross("The leader says you took the slope too fast, doesn't the leader?", "\"The leader may feel that way. I thought I was going slowly.\""), .cross("You knew the hitch pin was worn, didn't you?", "\"I'd heard it should be checked. I didn't replace it. I know I should have.\""), .cross("The mechanic left a note about the pin on your tractor seat, didn't the mechanic?", "\"There was a note on the seat. I did not take it seriously enough, and I have regretted that every day since.\""), .cross("Children were riding behind you on a slope, and you had been drinking, hadn't you?", "\"I had a couple of drinks earlier. I did not think I was impaired, and I will regret that decision for the rest of my life.\"")],
        openings: ("A trailer carrying a troop tipped on a hillside and killed {V}, a twelve-year-old. {D}, driving the tractor, blew a .12, and the troop leader says {DL} took the slope too fast. The State will present the trooper and the leader.", "The defense will point you to a worn hitch pin flagged by a mechanic, a steep slope, and a driver who felt the hitch give. Listen closely to the witnesses."),
        closings: ("A twelve-year-old killed, a driver at .12, and a leader who says the slope was taken too fast. {D} had the lives of a troop in {D.his} hands and drove after drinking.", "A worn hitch pin, a steep hill, and a trailer that tipped. The State must prove {D}'s drinking caused this, and a mechanical failure that no one can rule out is reasonable doubt."),
        timeline: [(0, "4 p.m.: the ride."), (0, "4:20 p.m.: the slope."), (0, "4:22 p.m.: the tip."), (0, "5 p.m.: {V} dies.")],
